--
-- Table structure for table `faq_items`
--

CREATE TABLE `faq_items` (
  `id` int NOT NULL,
  `question` text NOT NULL,
  `answer` text NOT NULL,
  `sort_order` int NOT NULL DEFAULT '0',
  `is_active` tinyint(1) DEFAULT '1',
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

--
-- Dumping data for table `faq_items`
--

INSERT INTO `faq_items` (`id`, `question`, `answer`, `sort_order`, `is_active`, `created_at`, `updated_at`) VALUES
(1, 'Apa itu Jagoansoal?', 'Jagoansoal adalah platform berbasis AI yang membantu guru dan pendidik membuat soal ujian secara otomatis. Cukup masukkan materi, AI kami akan menghasilkan soal lengkap dengan kunci jawaban dalam hitungan detik.', 1, 1, '2026-06-02 13:12:27', '2026-06-08 11:22:10'),
(2, 'Apakah benar-benar gratis?', 'Ya! Setiap pengguna baru mendapatkan 3 kredit gratis yang bisa digunakan untuk generate soal. Jika ingin lebih, Anda bisa top up dengan harga Rp 1.000 untuk 3 kredit, tanpa kedaluwarsa.', 2, 1, '2026-06-02 13:12:27', '2026-06-02 13:12:27'),
(3, 'Berapa lama proses generate soal?', 'Proses generate soal biasanya hanya memakan waktu 10-30 detik, tergantung pada jumlah soal dan kompleksitas materi. Jauh lebih cepat daripada menyusun soal secara manual.', 3, 1, '2026-06-02 13:12:27', '2026-06-02 13:12:27'),
(4, 'Format soal apa saja yang tersedia?', 'Kami mendukung berbagai jenis soal: Pilihan Ganda, Esai, Isian Singkat, Menjodohkan, dan Benar/Salah. Semua bisa dikombinasikan dalam satu paket ujian.', 4, 1, '2026-06-02 13:12:27', '2026-06-02 13:12:27'),
(5, 'Mata pelajaran apa saja yang didukung?', 'Jagoansoal mendukung berbagai mata pelajaran termasuk Matematika, Fisika, Kimia, Biologi, Bahasa Indonesia, Bahasa Inggris, Sejarah, Geografi, Ekonomi, dan masih banyak lagi.', 5, 1, '2026-06-02 13:12:27', '2026-06-02 16:49:50'),
(6, 'Apakah data saya aman?', 'Keamanan data adalah prioritas kami. Semua soal dan materi yang Anda buat bersifat pribadi dan tidak dibagikan ke pihak lain. Kami menggunakan enkripsi untuk melindungi data Anda.', 6, 1, '2026-06-02 13:12:27', '2026-06-02 13:12:27');

