INSERT INTO `how_it_works` (`id`, `step_number`, `title`, `description`, `is_active`, `created_at`, `updated_at`) VALUES
(1, 1, 'Masukkan Materi atau Topik', 'Tulis materi pelajaran, tempelkan teks, atau unggah dokumen. AI akan menganalisis dan memahami konteks pembelajaran Anda.', 1, '2026-06-05 12:12:52', '2026-06-05 12:12:52'),
(2, 2, 'Atur Parameter Soal', 'Pilih jumlah soal, jenis soal (pilihan ganda, esai, isian), tingkat kesulitan, dan mata pelajaran. Sesuaikan dengan kebutuhan.', 1, '2026-06-05 12:12:52', '2026-06-05 12:12:52'),
(3, 3, 'Generate & Export', 'AI langsung menghasilkan soal lengkap dengan kunci jawaban. Siap digunakan!', 1, '2026-06-05 12:12:52', '2026-06-05 12:12:52');

