) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

--
-- Dumping data for table `materials`
--

INSERT INTO `materials` (`id`, `user_id`, `subject_id`, `title`, `content`, `file_path`, `created_at`) VALUES
(3, 'Quv1ojcbZiS0QjT6IIsujK8rBWf1', 29, 'Instalasi Server', 'Fokus utama ke proses teknis dan teori dari instalasi web server untuk pemerograman web, mulai dari xampp, laragon, php native dan lain2 ya', NULL, '2026-06-01 14:23:11'),
(4, 'Quv1ojcbZiS0QjT6IIsujK8rBWf1', 29, 'Sejarah Penjajahan Belanda Di Indonesia', 'Sejarah penjajahan Belanda di Indonesia dimulai pada akhir abad ke-16 ketika ekspedisi Belanda pertama yang dipimpin Cornelis de Houtman mendarat di Banten pada tahun 1596. Pada tahun 1602, Vereenigde Oostindische Compagnie atau VOC didirikan sebagai kongsi dagang yang mendapat hak istimewa dari pemerintah Belanda untuk memonopoli perdagangan rempah-rempah di Nusantara. VOC mulai memperluas kekuasaannya dengan merebut Jayakarta pada tahun 1619 dan mengganti namanya menjadi Batavia sebagai pusat pemerintahan. Selama abad ke-17 dan ke-18, VOC menghadapi berbagai perlawanan dari kerajaan-kerajaan lokal seperti Kesultanan Mataram, Kesultanan Banten, dan Kesultanan Makassar, namun juga berhasil menguasai sebagian besar wilayah Indonesia melalui perjanjian dan peperangan. Namun, akibat korupsi dan manajemen yang buruk, VOC mengalami kebangkrutan dan resmi dibubarkan pada tanggal 31 Desember 1799, dengan seluruh asetnya diambil alih oleh pemerintah Hindia Belanda.\n\nSetelah VOC bubar, Indonesia berada di bawah pemerintahan langsung Belanda. Pada masa Gubernur Jenderal Herman Willem Daendels yang memerintah dari tahun 1808 hingga 1811, ia membangun jalan raya pos dari Anyer hingga Panarukan serta memberlakukan kerja paksa yang sangat memberatkan rakyat. Pada tahun 1811, Belanda menyerah kepada Inggris akibat Perang Napoleon, dan Indonesia sempat dikuasai Inggris di bawah Thomas Stamford Raffles hingga tahun 1816. Raffles menerapkan sistem sewa tanah dan menghapus kerja paksa, namun pemerintahannya tidak berlangsung lama. Setelah Inggris mengembalikan kekuasaan kepada Belanda pada tahun 1816, Belanda kembali menerapkan kebijakan kolonial yang ketat. Puncaknya adalah penerapan Sistem Tanam Paksa atau Cultuurstelsel pada tahun 1830 di bawah Gubernur Jenderal Johannes van den Bosch, yang mewajibkan petani menanam tanaman ekspor seperti kopi, tebu, dan nila. Sistem ini berlangsung hingga tahun 1870 dan membawa keuntungan besar bagi Belanda namun menyebabkan kemiskinan dan kelaparan di kalangan rakyat. Perlawanan besar terjadi pada periode ini, seperti Perang Padri di Sumatera Barat yang berlangsung dari tahun 1803 hingga 1838, serta Perang Diponegoro di Jawa Tengah dan Yogyakarta dari tahun 1825 hingga 1830 yang merupakan salah satu perlawanan terbesar terhadap Belanda.\n\nMemasuki abad ke-20, Belanda mulai menerapkan Politik Etis yang diumumkan oleh Ratu Wilhelmina pada tahun 1901, yang meliputi tiga program utama yaitu irigasi, edukasi, dan emigrasi. Politik Etis membuka akses pendidikan bagi pribumi, yang kemudian melahirkan kaum intelektual dan organisasi pergerakan nasional. Budi Utomo didirikan pada tahun 1908 sebagai organisasi modern pertama, disusul Sarekat Islam pada tahun 1912 dan Indische Partij pada tahun yang sama. Pergerakan semakin radikal dengan berdirinya Partai Komunis Indonesia pada tahun 1914 dan Partai Nasional Indonesia pada tahun 1927. Puncak semangat persatuan ditandai dengan Sumpah Pemuda pada tanggal 28 Oktober 1928 yang mengikrarkan satu tanah air, satu bangsa, dan satu bahasa. Penjajahan Belanda di Indonesia berakhir pada tahun 1942 ketika Jepang berhasil menduduki Indonesia setelah Belanda menyerah pada tanggal 8 Maret 1942. Namun, setelah Jepang kalah dalam Perang Dunia II, Belanda berusaha kembali menjajah Indonesia melalui Agresi Militer I pada tahun 1947 dan Agresi Militer II pada tahun 1948. Perlawanan rakyat dan tekanan internasional akhirnya memaksa Belanda mengakui kedaulatan Indonesia pada tanggal 27 Desember 1949 melalui Konferensi Meja Bundar, sehingga secara resmi berakhirlah penjajahan Belanda di Indonesia.', NULL, '2026-06-04 15:33:13');

