--

INSERT INTO `questions` (`id`, `user_id`, `subject_id`, `title`, `class`, `difficulty`, `type`, `total_questions`, `questions_data`, `prompt_used`, `created_at`) VALUES
(7, 'Quv1ojcbZiS0QjT6IIsujK8rBWf1', 29, 'Variable Di Php', 'SIA1', 'easy', 'multiple_choice', 5, '[{\"answer\": \"$nama = \'Andi\';\", \"options\": [\"var $nama;\", \"$nama = \'Andi\';\", \"int $nama = 10;\", \"variable nama = \'Budi\';\"], \"question\": \"Dalam PHP, manakah dari berikut ini yang merupakan cara yang benar untuk mendeklarasikan sebuah variabel?\", \"explanation\": \"Di PHP, variabel dideklarasikan dengan tanda $ diikuti nama variabel, tanpa perlu kata kunci khusus. Opsi B adalah contoh deklarasi dan inisialisasi yang benar.\"}, {\"answer\": \"10\", \"options\": [\"5\", \"10\", \"Error\", \"0\"], \"question\": \"Perhatikan kode PHP berikut:\\n\\n<?php\\n$x = 5;\\n$y = &$x;\\n$y = 10;\\necho $x;\\n?>\\n\\nApa output dari kode tersebut?\", \"explanation\": \"Dengan operator referensi (&), $y menjadi referensi ke $x. Mengubah $y juga mengubah $x, sehingga $x bernilai 10.\"}, {\"answer\": \"$nama_saya\", \"options\": [\"$2nama\", \"$nama_saya\", \"$nama-saya\", \"$nama saya\"], \"question\": \"Manakah dari berikut ini yang merupakan nama variabel PHP yang valid?\", \"explanation\": \"Nama variabel PHP harus diawali dengan huruf atau underscore, dan hanya boleh mengandung huruf, angka, dan underscore. Opsi B memenuhi aturan tersebut.\"}, {\"answer\": \"Variabel yang namanya dapat ditentukan secara dinamis menggunakan nilai variabel lain\", \"options\": [\"Variabel yang nilainya berupa variabel lain\", \"Variabel yang namanya dapat ditentukan secara dinamis menggunakan nilai variabel lain\", \"Variabel yang hanya bisa diakses di dalam fungsi\", \"Variabel yang memiliki tipe data dinamis\"], \"question\": \"Dalam PHP, apa yang dimaksud dengan variable variables?\", \"explanation\": \"Variable variables memungkinkan penggunaan nilai dari suatu variabel sebagai nama variabel lain, misalnya $$var.\"}, {\"answer\": \"10\", \"options\": [\"5\", \"10\", \"Error\", \"Tidak ada output\"], \"question\": \"Perhatikan kode PHP berikut:\\n\\n<?php\\nfunction test() {\\n    $a = 5;\\n    global $a;\\n    echo $a;\\n}\\n$a = 10;\\ntest();\\n?>\\n\\nApa output dari kode tersebut?\", \"explanation\": \"Dengan keyword global di dalam fungsi, $a merujuk pada variabel global $a yang bernilai 10, sehingga outputnya 10.\"}]', 'Variable Di Php', '2026-06-01 14:30:45'),
(8, 'Quv1ojcbZiS0QjT6IIsujK8rBWf1', 29, 'Fokus ke teori pemerograman web ya', 'SIA1', 'medium', 'mixed', 5, '[{\"answer\": \"Model\", \"options\": [\"Model\", \"View\", \"Controller\", \"Router\"], \"question\": \"Dalam arsitektur MVC (Model-View-Controller), komponen mana yang bertanggung jawab menangani logika bisnis dan interaksi dengan database?\", \"explanation\": \"Model berisi logika bisnis dan berinteraksi dengan database untuk mengelola data.\"}, {\"answer\": \"PUT\", \"options\": [\"GET\", \"POST\", \"PUT\", \"DELETE\"], \"question\": \"Metode HTTP manakah yang umumnya digunakan untuk memperbarui data secara keseluruhan (full update) pada RESTful API?\", \"explanation\": \"PUT digunakan untuk mengganti seluruh representasi sumber daya, sedangkan PATCH untuk pembaruan parsial.\"}, {\"answer\": \"AJAX\", \"options\": [\"WebSocket\", \"AJAX\", \"Server-Sent Events\", \"Fetch API\"], \"question\": \"Teknologi apa yang memungkinkan halaman web untuk mengirim dan menerima data dari server secara asynchronous tanpa harus me-refresh halaman?\", \"explanation\": \"AJAX (Asynchronous JavaScript and XML) memungkinkan komunikasi asynchronous dengan server, meskipun Fetch API juga bisa, namun AJAX adalah istilah umum yang lebih dikenal.\"}, {\"answer\": \"Session disimpan di server, cookie disimpan di klien\", \"options\": [\"Cookie disimpan di server, session disimpan di klien\", \"Session disimpan di server, cookie disimpan di klien\", \"Cookie dan session sama-sama disimpan di server\", \"Cookie dan session sama-sama disimpan di klien\"], \"question\": \"Manakah pernyataan yang benar tentang session dan cookie dalam pengembangan web?\", \"explanation\": \"Session data disimpan di server, sedangkan cookie disimpan di browser klien untuk mengidentifikasi session.\"}, {\"answer\": \"Memproses request sebelum mencapai controller\", \"options\": [\"Menghubungkan model dengan view\", \"Menangani routing URL\", \"Memproses request sebelum mencapai controller\", \"Menyediakan template engine\"], \"question\": \"Dalam framework web seperti Laravel atau Express.js, apa fungsi utama dari middleware?\", \"explanation\": \"Middleware berfungsi sebagai lapisan yang memproses request (misal: autentikasi, logging) sebelum diteruskan ke controller.\"}]', 'Fokus ke teori pemerograman web ya', '2026-06-01 14:39:10'),
(9, 'Quv1ojcbZiS0QjT6IIsujK8rBWf1', 29, 'Fokus ke framework ya', 'SIA1', 'medium', 'mixed', 5, '[{\"answer\": \"MVC (Model-View-Controller) adalah pola arsitektur yang memisahkan logika bisnis (Model), tampilan (View), dan kontrol alur (Controller). Dalam Laravel, Model berinteraksi dengan database, View menampilkan data, dan Controller menangani permintaan serta mengatur respons. Penerapannya memudahkan pengelolaan kode, pengujian, dan pengembangan secara terstruktur.\", \"question\": \"Jelaskan konsep MVC dalam framework Laravel dan bagaimana penerapannya dalam pengembangan aplikasi web!\", \"explanation\": \"Pola MVC membantu developer memisahkan tanggung jawab, sehingga kode lebih modular dan mudah dipelihara. Laravel mengimplementasikannya secara ketat dengan direktori khusus untuk Model, View, dan Controller.\"}, {\"answer\": \"Kelebihan framework: menyediakan struktur terorganisir, fitur bawaan seperti ORM, routing, autentikasi, dan keamanan; mempercepat pengembangan; dan memudahkan kolaborasi. Kekurangan: kurva belajar lebih tinggi, performa bisa lebih lambat karena overhead, dan terkadang membatasi fleksibilitas jika kebutuhan spesifik.\", \"question\": \"Bandingkan kelebihan dan kekurangan penggunaan framework (seperti Laravel) dibandingkan dengan coding native dalam pengembangan web!\", \"explanation\": \"Framework menawarkan solusi siap pakai untuk masalah umum, namun untuk proyek sederhana atau yang membutuhkan kontrol penuh, native coding mungkin lebih efisien.\"}, {\"answer\": \"Routing di Laravel mendefinisikan URL dan metode HTTP yang dipetakan ke Closure atau Controller. Contoh: Route::get(\'/profil/{id}\', [ProfilController::class, \'tampilkan\'])->name(\'profil\');. Route ini akan menangani permintaan GET ke /profil/1 dan memanggil method tampilkan di ProfilController dengan parameter id.\", \"question\": \"Jelaskan cara kerja routing di Laravel! Berikan contoh sederhana penerapan route untuk menampilkan halaman profil pengguna!\", \"explanation\": \"Routing memungkinkan pengelolaan endpoint aplikasi secara terpusat. Laravel mendukung parameter, middleware, dan penamaan route untuk kemudahan referensi.\"}, {\"answer\": \"Eloquent ORM adalah implementasi Active Record di Laravel yang memungkinkan developer berinteraksi dengan database menggunakan objek PHP, bukan SQL mentah. Keuntungan: sintaks yang intuitif, relasi antar tabel mudah diatur, query builder yang aman dari SQL injection, dan mendukung migrasi serta seeding.\", \"question\": \"Apa yang dimaksud dengan Eloquent ORM dalam Laravel? Jelaskan keuntungan utama menggunakannya dalam interaksi database!\", \"explanation\": \"Dengan Eloquent, setiap tabel database diwakili oleh Model. Contoh: User::where(\'aktif\', true)->get();. Ini mempercepat pengembangan dan mengurangi risiko kesalahan.\"}, {\"answer\": \"Migrasi adalah fitur untuk mengelola skema database secara terprogram. Prosesnya: buat file migrasi dengan perintah \'php artisan make:migration\', definisikan perubahan (create, alter, drop) menggunakan Schema Builder, lalu jalankan \'php artisan migrate\'. Migrasi penting karena memungkinkan setiap anggota tim memiliki struktur database yang sinkron, memudahkan rollback, dan mendukung version control.\", \"question\": \"Jelaskan proses migrasi database di Laravel! Mengapa migrasi penting dalam pengembangan aplikasi berbasis tim?\", \"explanation\": \"Migrasi menghindari inkonsistensi database antar lingkungan (dev, staging, production) dan memudahkan deployment otomatis.\"}]', 'Fokus ke framework ya', '2026-06-01 14:41:35'),
(10, 'Quv1ojcbZiS0QjT6IIsujK8rBWf1', 29, 'Algoritma mesin learning', 'SIA1', 'medium', 'multiple_choice', 5, '[{\"answer\": \"Naive Bayes\", \"options\": [\"Regresi Linear\", \"Naive Bayes\", \"K-Means\", \"Apriori\"], \"question\": \"Algoritma machine learning yang sering digunakan untuk klasifikasi teks pada aplikasi web, seperti filter spam, adalah...\", \"explanation\": \"Naive Bayes efektif untuk klasifikasi teks karena bekerja berdasarkan probabilitas kata-kata dalam dokumen.\"}, {\"answer\": \"TensorFlow.js\", \"options\": [\"TensorFlow.js\", \"PyTorch\", \"Scikit-learn\", \"Keras\"], \"question\": \"Library JavaScript yang populer untuk menjalankan model machine learning di sisi klien (browser) adalah...\", \"explanation\": \"TensorFlow.js memungkinkan eksekusi model ML langsung di browser tanpa server.\"}, {\"answer\": \"Regresi Linear\", \"options\": [\"Regresi Linear\", \"Klasifikasi\", \"Clustering\", \"Asosiasi\"], \"question\": \"Algoritma supervised learning yang cocok untuk memprediksi nilai kontinu seperti harga rumah berdasarkan fitur (luas, jumlah kamar) adalah...\", \"explanation\": \"Regresi Linear digunakan untuk memprediksi nilai numerik kontinu.\"}, {\"answer\": \"JSON\", \"options\": [\"JSON\", \"XML\", \"CSV\", \"HTML\"], \"question\": \"REST API yang digunakan untuk mengirim data ke model machine learning yang di-deploy di cloud biasanya menggunakan format data...\", \"explanation\": \"JSON adalah format standar dan ringan untuk pertukaran data pada REST API.\"}, {\"answer\": \"K-Means\", \"options\": [\"K-Means\", \"Regresi Logistik\", \"Random Forest\", \"Support Vector Machine\"], \"question\": \"Algoritma unsupervised learning yang sering digunakan untuk segmentasi pelanggan pada aplikasi e-commerce adalah...\", \"explanation\": \"K-Means adalah algoritma clustering yang mengelompokkan data berdasarkan kemiripan fitur.\"}]', 'Algoritma mesin learning', '2026-06-01 14:51:01'),
(12, 'Quv1ojcbZiS0QjT6IIsujK8rBWf1', 29, 'variabel diphp', 'SIA1', 'hard', 'multiple_choice', 5, '[{\"answer\": \"world\", \"options\": [\"hello\", \"world\", \"error\", \"null\"], \"question\": \"Dalam PHP, jika Anda memiliki kode berikut: $a = \'hello\'; $$a = \'world\'; echo $hello; Apakah outputnya?\", \"explanation\": \"$$a adalah variable variables, yang mengacu pada variabel dengan nama yang sama dengan nilai $a. Karena $a = \'hello\', maka $$a setara dengan $hello, sehingga $hello = \'world\'.\"}, {\"answer\": \"15\", \"options\": [\"10\", \"15\", \"error\", \"5\"], \"question\": \"Perhatikan fungsi berikut: function tambah(&$x) { $x += 5; } $num = 10; tambah($num); echo $num; Berapa outputnya?\", \"explanation\": \"Parameter &$x adalah pass by reference, sehingga perubahan pada $x di dalam fungsi mempengaruhi variabel asli $num. Nilai $num menjadi 15.\"}, {\"answer\": \"123\", \"options\": [\"111\", \"123\", \"012\", \"3\"], \"question\": \"Fungsi berikut menggunakan static variable: function counter() { static $count = 0; $count++; return $count; } echo counter() . counter() . counter(); Apakah outputnya?\", \"explanation\": \"Static variable $count mempertahankan nilainya antar panggilan fungsi. Setiap panggilan menambah 1, sehingga output berturut-turut adalah 1, 2, 3.\"}, {\"answer\": \"Variabel global dianggap sebagai variabel lokal baru\", \"options\": [\"Variabel global dapat diakses langsung\", \"Akan menghasilkan error\", \"Variabel global dianggap sebagai variabel lokal baru\", \"Nilai variabel global akan diubah\"], \"question\": \"Dalam PHP, apa yang terjadi jika Anda mengakses variabel global di dalam fungsi tanpa kata kunci global atau array $GLOBALS?\", \"explanation\": \"Di dalam fungsi, variabel global tidak dapat diakses secara langsung. Jika Anda menggunakan nama variabel yang sama tanpa deklarasi global, PHP akan membuat variabel lokal baru dengan nama tersebut.\"}, {\"answer\": \"integer 15\", \"options\": [\"integer 15\", \"string \'510\'\", \"float 15.0\", \"error karena tipe tidak cocok\"], \"question\": \"Perhatikan kode: $a = \'5\'; $b = 10; $c = $a + $b; echo $c; Apakah tipe data dan nilai dari $c?\", \"explanation\": \"PHP melakukan type juggling secara otomatis. String \'5\' dikonversi menjadi integer 5, sehingga hasil penjumlahan adalah 15 (integer).\"}]', 'variabel diphp', '2026-06-02 13:21:40'),
(13, 'V0pHPx3UHgUjpjqowQ9Iay0SZHG2', 32, 'Sejarah Perumusan Pancasila', '12 SMA', 'hard', 'multiple_choice', 5, '[{\"answer\": \"Asas dan Dasar Negara Indonesia Merdeka\", \"options\": [\"Asas dan Dasar Negara Indonesia Merdeka\", \"Pembukaan dan Dasar Negara Indonesia Merdeka\", \"Rumusan Dasar Negara Indonesia Merdeka\", \"Piagam Dasar Negara Indonesia Merdeka\"], \"question\": \"Dalam sidang BPUPKI pertama, Muhammad Yamin mengusulkan rumusan dasar negara secara lisan pada tanggal 29 Mei 1945. Salah satu poin dalam usulan tersebut adalah \'Peri Ketuhanan\'. Namun, dalam naskah tertulis yang diserahkan kepada ketua sidang, usulan tersebut memiliki judul yang berbeda. Apa judul naskah tertulis yang diserahkan oleh Muhammad Yamin?\", \"image_url\": \"/public/assets/question/images/q_1780727663_c059f944.png\", \"explanation\": \"Muhammad Yamin menyampaikan usulan secara lisan pada 29 Mei 1945 dengan lima asas, dan kemudian menyerahkan naskah tertulis berjudul \'Asas dan Dasar Negara Indonesia Merdeka\' pada 31 Mei 1945. Judul ini berbeda dengan yang disampaikan secara lisan.\"}, {\"answer\": \"Mohammad Hatta, karena khawatir akan menimbulkan disintegrasi bangsa\", \"options\": [\"Mohammad Hatta, karena khawatir akan menimbulkan disintegrasi bangsa\", \"Soekarno, karena ingin menonjolkan nilai ketuhanan yang universal\", \"Ahmad Subardjo, karena menyesuaikan dengan konsep negara kesatuan\", \"Ki Bagus Hadikusumo, karena menginginkan rumusan yang lebih tegas\"], \"question\": \"Dalam proses perumusan Pancasila, Panitia Sembilan menghasilkan Piagam Jakarta pada 22 Juni 1945. Namun, terdapat perdebatan sengit mengenai sila pertama yang berbunyi \'Ketuhanan dengan kewajiban menjalankan syariat Islam bagi pemeluk-pemeluknya\'. Perubahan redaksional ini akhirnya disepakati pada tanggal 18 Agustus 1945. Siapa tokoh yang paling vokal mengusulkan perubahan tersebut dan apa alasan utamanya?\", \"explanation\": \"Mohammad Hatta menerima laporan dari utusan Kristen Indonesia bagian timur yang merasa keberatan dengan frasa \'syariat Islam\'. Untuk menjaga persatuan, Hatta mengusulkan perubahan menjadi \'Ketuhanan Yang Maha Esa\' pada sidang PPKI 18 Agustus 1945, yang kemudian disetujui.\"}, {\"answer\": \"Soepomo, dengan alasan integralistik dan kekeluargaan\", \"options\": [\"Soekarno, dengan alasan efektivitas pemerintahan dan sejarah Nusantara\", \"Mohammad Hatta, dengan alasan efisiensi administrasi dan kedaulatan rakyat\", \"Soepomo, dengan alasan integralistik dan kekeluargaan\", \"Muhammad Yamin, dengan alasan geopolitik dan pertahanan\"], \"question\": \"Pada sidang BPUPKI kedua (10-17 Juli 1945), dibentuk Panitia Perancang Undang-Undang Dasar yang diketuai oleh Soekarno. Panitia ini kemudian membentuk Panitia Kecil Perancang UUD yang diketuai oleh Soepomo. Namun, terdapat perbedaan pendapat mengenai bentuk negara. Siapa tokoh yang mengusulkan bentuk negara kesatuan dan bagaimana argumentasinya?\", \"image_url\": \"/public/assets/question/images/q_1780729534_4794d2f7.png\", \"explanation\": \"Dalam sidang BPUPKI, Soepomo mengusulkan negara kesatuan berdasarkan paham integralistik, di mana negara merupakan susunan masyarakat yang integral dan bersifat kekeluargaan. Ia menolak negara federal yang dianggap memecah belah persatuan.\"}, {\"answer\": \"Kelompok nasionalis sekuler menerima frasa tersebut dengan syarat ditambahkan klausa \'bagi pemeluk-pemeluknya\' untuk membatasi cakupan\", \"options\": [\"Kelompok Islam setuju untuk tidak mencantumkan frasa tersebut dalam pembukaan UUD, tetapi dimasukkan dalam pasal tersendiri\", \"Kelompok nasionalis sekuler menerima frasa tersebut dengan syarat ditambahkan klausa \'bagi pemeluk-pemeluknya\' untuk membatasi cakupan\", \"Kelompok Islam mengusulkan agar frasa tersebut hanya berlaku di Jawa, sementara di luar Jawa tidak mengikat\", \"Kelompok nasionalis sekuler mengusulkan agar kata \'Ketuhanan\' diganti dengan \'Tuhan\' untuk menghindari tafsir sempit\"], \"question\": \"Dalam perumusan Pancasila, terdapat perbedaan pandangan antara kelompok Islam dan kelompok nasionalis sekuler mengenai dasar negara. Salah satu titik kritis adalah saat pembahasan sila pertama dalam Panitia Sembilan. Bagaimana kompromi yang dicapai sehingga Piagam Jakarta tetap memuat frasa \'dengan kewajiban menjalankan syariat Islam bagi pemeluk-pemeluknya\'?\", \"explanation\": \"Kompromi dalam Panitia Sembilan adalah dengan menambahkan kalimat \'bagi pemeluk-pemeluknya\' setelah \'syariat Islam\', sehingga kewajiban tersebut hanya berlaku bagi umat Islam, bukan seluruh warga negara. Ini merupakan jalan tengah antara keinginan kelompok Islam dan kekhawatiran kelompok nasionalis.\"}, {\"answer\": \"Frasa \'dengan kewajiban menjalankan syariat Islam bagi pemeluk-pemeluknya\' dihapus menjadi \'Ketuhanan Yang Maha Esa\', diusulkan oleh Mohammad Hatta\", \"options\": [\"Frasa \'dengan kewajiban menjalankan syariat Islam bagi pemeluk-pemeluknya\' dihapus menjadi \'Ketuhanan Yang Maha Esa\', diusulkan oleh Mohammad Hatta\", \"Frasa \'Ketuhanan dengan kewajiban menjalankan syariat Islam\' diganti \'Ketuhanan Yang Maha Esa\', diusulkan oleh Ki Bagus Hadikusumo\", \"Urutan sila diubah sehingga sila pertama menjadi \'Kemanusiaan yang adil dan beradab\', diusulkan oleh Soepomo\", \"Penambahan kata \'Maha\' pada \'Ketuhanan\' menjadi \'Ketuhanan Yang Maha Esa\', diusulkan oleh Wachid Hasyim\"], \"question\": \"Setelah proklamasi kemerdekaan, PPKI mengadakan sidang pada 18 Agustus 1945 dan mengesahkan UUD 1945. Namun, dalam sidang tersebut terjadi perubahan pada Pembukaan UUD, khususnya pada alinea keempat yang memuat rumusan Pancasila. Perubahan apa yang dilakukan pada sila pertama dan siapa yang mengusulkannya secara langsung dalam sidang tersebut?\", \"explanation\": \"Dalam sidang PPKI 18 Agustus 1945, Mohammad Hatta mengusulkan penghapusan frasa \'dengan kewajiban menjalankan syariat Islam bagi pemeluk-pemeluknya\' setelah menerima masukan dari wakil Kristen Indonesia. Usulan ini disetujui oleh seluruh anggota sidang, termasuk tokoh Islam seperti Ki Bagus Hadikusumo dan Wachid Hasyim, demi persatuan bangsa.\"}]', 'Sejarah Perumusan Pancasila', '2026-06-02 13:55:05'),
(14, 'Quv1ojcbZiS0QjT6IIsujK8rBWf1', 29, 'Dasar-dasar pemerograman', 'SIA1', 'hard', 'multiple_choice', 5, '[{\"answer\": \"Pemilihan pivot selalu elemen terkecil atau terbesar\", \"options\": [\"Pemilihan pivot selalu elemen tengah\", \"Pemilihan pivot selalu elemen terkecil atau terbesar\", \"Menggunakan partisi dua arah\", \"Data sudah terurut secara acak\"], \"question\": \"Dalam algoritma quicksort, kondisi apa yang menyebabkan kompleksitas waktu terburuk O(n²)?\", \"explanation\": \"Jika pivot yang dipilih selalu merupakan elemen terkecil atau terbesar, partisi menjadi tidak seimbang (satu sisi kosong), sehingga rekursi terjadi n kali dengan total operasi O(n²).\"}, {\"answer\": \"10\", \"options\": [\"10\", \"100\", \"500\", \"1000\"], \"question\": \"Dalam algoritma binary search, berapa jumlah maksimum iterasi yang diperlukan untuk mencari elemen dalam array terurut berukuran 1000 elemen?\", \"explanation\": \"Binary search membagi ruang pencarian menjadi dua setiap iterasi. Jumlah maksimum iterasi adalah log₂(1000) ≈ 10, karena 2¹⁰ = 1024 > 1000.\"}, {\"answer\": \"O(2ⁿ)\", \"options\": [\"O(n)\", \"O(log n)\", \"O(2ⁿ)\", \"O(n²)\"], \"question\": \"Algoritma rekursif berikut digunakan untuk menghitung deret Fibonacci: fib(n) = fib(n-1) + fib(n-2) dengan fib(0)=0, fib(1)=1. Berapa kompleksitas waktu dari implementasi rekursif naif ini?\", \"explanation\": \"Setiap pemanggilan rekursif menghasilkan dua pemanggilan lagi, sehingga pohon rekursi memiliki tinggi n dan jumlah node eksponensial, yaitu O(2ⁿ).\"}, {\"answer\": \"Priority queue (heap)\", \"options\": [\"Array tidak terurut\", \"Linked list\", \"Priority queue (heap)\", \"Stack\"], \"question\": \"Dalam algoritma Djikstra untuk shortest path, struktur data apa yang paling efisien digunakan untuk memilih simpul dengan jarak minimum pada setiap iterasi?\", \"explanation\": \"Priority queue memungkinkan ekstraksi minimum dalam O(log n) dan update jarak dalam O(log n), lebih efisien daripada array (O(n)) atau linked list (O(n)).\"}, {\"answer\": \"3 koin (4+1+1)\", \"options\": [\"3 koin (4+1+1)\", \"2 koin (3+3)\", \"4 koin (1+1+1+1+1+1)\", \"1 koin (6 tidak tersedia)\"], \"question\": \"Dalam algoritma greedy untuk masalah penukaran koin, jika tersedia koin 1, 3, dan 4, dan kita ingin menukar uang sebesar 6, apa hasil yang diberikan algoritma greedy (ambil koin terbesar dulu)?\", \"explanation\": \"Greedy akan memilih koin 4 (sisa 2), lalu 1 (sisa 1), lalu 1, total 3 koin. Solusi optimal adalah 2 koin (3+3), tetapi greedy gagal karena tidak mempertimbangkan kombinasi yang lebih kecil.\"}]', 'Dasar-dasar pemerograman', '2026-06-03 06:15:05'),
(15, 'Quv1ojcbZiS0QjT6IIsujK8rBWf1', 29, 'fokus ke framework js ya', 'SIA1', 'easy', 'multiple_choice', 5, '[{\"answer\": \"B. Kerangka kerja untuk memudahkan pengembangan aplikasi web\", \"options\": [\"A. Library untuk styling\", \"B. Kerangka kerja untuk memudahkan pengembangan aplikasi web\", \"C. Bahasa pemrograman\", \"D. Database\"], \"question\": \"Apa yang dimaksud dengan framework JavaScript?\", \"explanation\": \"Framework JavaScript menyediakan struktur dan alat bantu untuk mempercepat dan memudahkan pengembangan aplikasi web.\"}, {\"answer\": \"C. React\", \"options\": [\"A. Laravel\", \"B. Django\", \"C. React\", \"D. Flask\"], \"question\": \"Manakah dari berikut ini yang termasuk framework JavaScript front-end?\", \"explanation\": \"React adalah library/framework JavaScript yang populer untuk membangun antarmuka pengguna di sisi front-end.\"}, {\"answer\": \"A. Membangun UI interaktif\", \"options\": [\"A. Membangun UI interaktif\", \"B. Mengelola database\", \"C. Menulis CSS\", \"D. Mengatur server\"], \"question\": \"Apa fungsi utama dari Vue.js?\", \"explanation\": \"Vue.js adalah framework JavaScript yang digunakan untuk membangun antarmuka pengguna yang interaktif dan reaktif.\"}, {\"answer\": \"C. Angular\", \"options\": [\"A. React\", \"B. Vue\", \"C. Angular\", \"D. jQuery\"], \"question\": \"Framework JavaScript yang dikembangkan oleh Google adalah...\", \"explanation\": \"Angular adalah framework JavaScript yang dikembangkan dan dikelola oleh Google.\"}, {\"answer\": \"A. Mempercepat pengembangan\", \"options\": [\"A. Mempercepat pengembangan\", \"B. Menambah beban server\", \"C. Memperlambat aplikasi\", \"D. Tidak memiliki dokumentasi\"], \"question\": \"Apa keuntungan menggunakan framework JavaScript?\", \"explanation\": \"Framework JavaScript menyediakan komponen siap pakai dan struktur yang jelas, sehingga mempercepat proses pengembangan aplikasi.\"}]', 'fokus ke framework js ya', '2026-06-03 06:25:54'),
(16, 'Quv1ojcbZiS0QjT6IIsujK8rBWf1', 29, 'Sejarah Pki', 'SIA1', 'easy', 'multiple_choice', 5, '[{\"answer\": \"Ketidakpuasan terhadap hasil Perjanjian Renville; dalangnya Musso\", \"options\": [\"Ketidakpuasan terhadap hasil Perjanjian Renville; dalangnya Musso\", \"Persaingan dengan TNI; dalangnya D.N. Aidit\", \"Pengaruh dari Uni Soviet; dalangnya Alimin\", \"Keinginan mendirikan negara komunis; dalangnya Tan Malaka\"], \"question\": \"Apa alasan utama yang mendorong PKI untuk melancarkan pemberontakan pada tahun 1948 di Madiun, dan siapa dalang di balik peristiwa tersebut?\", \"explanation\": \"Pemberontakan PKI Madiun 1948 dipicu oleh ketidakpuasan terhadap Perjanjian Renville yang dianggap merugikan Republik Indonesia, dan dipimpin oleh Musso yang baru kembali dari Uni Soviet.\"}, {\"answer\": \"Untuk mencegah kudeta yang direncanakan oleh Dewan Jenderal\", \"options\": [\"Untuk mencegah kudeta yang direncanakan oleh Dewan Jenderal\", \"Sebagai balas dendam atas pembantaian anggota PKI di tahun 1965\", \"Untuk merebut kekuasaan secara langsung dan mendirikan negara komunis\", \"Atas perintah langsung dari Presiden Soekarno\"], \"question\": \"Dalam peristiwa G30S/PKI, apa motif utama yang mendorong D.N. Aidit dan kelompoknya untuk menculik dan membunuh para jenderal TNI AD?\", \"explanation\": \"PKI di bawah D.N. Aidit mengklaim bahwa Dewan Jenderal akan melakukan kudeta pada 5 Oktober 1965, sehingga G30S bertujuan untuk menggagalkan rencana tersebut, meskipun klaim ini tidak pernah terbukti.\"}, {\"answer\": \"Ia tewas dalam baku tembak dengan TNI di Pegunungan Kendeng\", \"options\": [\"Ia ditangkap dan dijatuhi hukuman mati\", \"Ia tewas dalam baku tembak dengan TNI di Pegunungan Kendeng\", \"Ia melarikan diri ke luar negeri dan meninggal di Tiongkok\", \"Ia diampuni oleh Soekarno dan kemudian menjadi anggota DPR\"], \"question\": \"Apa akhir dari pelaku utama pemberontakan PKI Madiun 1948, Musso, setelah peristiwa tersebut?\", \"explanation\": \"Musso tewas dalam pertempuran dengan pasukan TNI pada September 1948 di daerah Pegunungan Kendeng, Jawa Timur, setelah pemberontakan berhasil dipadamkan.\"}, {\"answer\": \"Ia tewas dalam operasi militer di daerah pedalaman Jawa Tengah\", \"options\": [\"Ia ditangkap dan diadili, kemudian dijatuhi hukuman mati\", \"Ia berhasil melarikan diri ke Kamboja dan meninggal di sana\", \"Ia tewas dalam operasi militer di daerah pedalaman Jawa Tengah\", \"Ia diasingkan ke Pulau Buru dan meninggal karena sakit\"], \"question\": \"Setelah peristiwa G30S/PKI, bagaimana nasib D.N. Aidit yang menjadi dalang utama gerakan tersebut?\", \"explanation\": \"D.N. Aidit ditangkap pada November 1965 di Jawa Tengah, dan kemudian dilaporkan tewas dalam operasi militer, meskipun ada versi yang menyatakan ia dieksekusi secara diam-diam.\"}, {\"answer\": \"Pengaruh dari doktrin Maoisme yang menganjurkan revolusi bersenjata\", \"options\": [\"Adanya dukungan dari petani dan buruh yang radikal\", \"Pengaruh dari doktrin Maoisme yang menganjurkan revolusi bersenjata\", \"Kekalahan dalam pemilu lokal yang membuat PKI kehilangan basis massa\", \"Tekanan dari Uni Soviet untuk segera melakukan revolusi komunis\"], \"question\": \"Apa alasan yang mendorong PKI di bawah pimpinan Musso untuk memilih jalur pemberontakan bersenjata pada tahun 1948, berbeda dengan strategi sebelumnya yang lebih moderat?\", \"explanation\": \"Musso yang baru kembali dari luar negeri membawa pengaruh Maoisme, yang menekankan pentingnya perjuangan bersenjata untuk merebut kekuasaan, menggantikan strategi perjuangan parlementer yang sebelumnya dijalankan PKI.\"}]', 'Sejarah Pki', '2026-06-03 06:30:23'),
(17, 'Quv1ojcbZiS0QjT6IIsujK8rBWf1', 29, 'fokus ke framework js ya', 'SIA1', 'easy', 'multiple_choice', 5, '[{\"answer\": \"B. Kerangka kerja untuk memudahkan pengembangan aplikasi web\", \"options\": [\"A. Library untuk styling\", \"B. Kerangka kerja untuk memudahkan pengembangan aplikasi web\", \"C. Bahasa pemrograman\", \"D. Database\"], \"question\": \"Apa yang dimaksud dengan framework JavaScript?\", \"explanation\": \"Framework JavaScript menyediakan struktur dan alat bantu untuk mempercepat dan memudahkan pengembangan aplikasi web.\"}, {\"answer\": \"C. React\", \"options\": [\"A. Laravel\", \"B. Django\", \"C. React\", \"D. Flask\"], \"question\": \"Manakah dari berikut ini yang termasuk framework JavaScript front-end?\", \"explanation\": \"React adalah library/framework JavaScript yang populer untuk membangun antarmuka pengguna di sisi front-end.\"}, {\"answer\": \"A. Membangun UI interaktif\", \"options\": [\"A. Membangun UI interaktif\", \"B. Mengelola database\", \"C. Menulis CSS\", \"D. Mengatur server\"], \"question\": \"Apa fungsi utama dari Vue.js?\", \"explanation\": \"Vue.js adalah framework JavaScript yang digunakan untuk membangun antarmuka pengguna yang interaktif dan reaktif.\"}, {\"answer\": \"C. Angular\", \"options\": [\"A. React\", \"B. Vue\", \"C. Angular\", \"D. jQuery\"], \"question\": \"Framework JavaScript yang dikembangkan oleh Google adalah...\", \"explanation\": \"Angular adalah framework JavaScript yang dikembangkan dan dikelola oleh Google.\"}, {\"answer\": \"A. Mempercepat pengembangan\", \"options\": [\"A. Mempercepat pengembangan\", \"B. Menambah beban server\", \"C. Memperlambat aplikasi\", \"D. Tidak memiliki dokumentasi\"], \"question\": \"Apa keuntungan menggunakan framework JavaScript?\", \"explanation\": \"Framework JavaScript menyediakan komponen siap pakai dan struktur yang jelas, sehingga mempercepat proses pengembangan aplikasi.\"}]', 'fokus ke framework js ya', '2026-06-03 06:56:02'),
(18, 'Quv1ojcbZiS0QjT6IIsujK8rBWf1', 29, 'Fokus ke latihan mencari bug di kode ya', 'SIA1', 'medium', 'mixed', 5, '[{\"answer\": \"SQL Injection\", \"options\": [\"Cross-Site Scripting (XSS)\", \"SQL Injection\", \"Remote File Inclusion\", \"Broken Authentication\"], \"question\": \"Perhatikan kode PHP berikut:\\n\\n$id = $_GET[\'id\'];\\n$query = \\\"SELECT * FROM users WHERE id = $id\\\";\\n$result = mysqli_query($conn, $query);\\n\\nApa jenis bug yang terdapat pada kode tersebut?\", \"explanation\": \"Variabel $id langsung dimasukkan ke query tanpa sanitasi, memungkinkan attacker menyisipkan perintah SQL.\"}, {\"answer\": \"Cross-Site Scripting (XSS)\", \"options\": [\"Denial of Service (DoS)\", \"Cross-Site Scripting (XSS)\", \"SQL Injection\", \"Man-in-the-Middle (MitM)\"], \"question\": \"Kode JavaScript berikut digunakan untuk menampilkan input pengguna:\\n\\ndocument.getElementById(\'output\').innerHTML = userInput;\\n\\nBug keamanan apa yang paling mungkin terjadi?\", \"explanation\": \"innerHTML akan mengeksekusi HTML/JavaScript dari input pengguna, memungkinkan serangan XSS.\"}, {\"answer\": \"Array index out of bounds karena menggunakan <= bukan <\", \"options\": [\"Infinite loop karena kondisi salah\", \"Array index out of bounds karena menggunakan <= bukan <\", \"Variabel $i tidak diinisialisasi\", \"Fungsi count() tidak valid untuk array\"], \"question\": \"Perhatikan potongan kode PHP berikut:\\n\\nfor ($i = 0; $i <= count($array); $i++) {\\n    echo $array[$i];\\n}\\n\\nApa bug yang terdapat dalam loop tersebut?\", \"explanation\": \"Jika array memiliki n elemen, indeks valid 0 hingga n-1. Loop dengan <= akan mengakses indeks n yang tidak ada.\"}, {\"answer\": \"Bug: Tidak ada validasi tipe file, ukuran file, atau pengecekan apakah file sudah ada. Attacker bisa mengunggah file berbahaya seperti .php. Perbaikan: Validasi ekstensi file, batasi ukuran, dan cek apakah file sudah ada sebelum menyimpan.\", \"question\": \"Temukan bug pada kode PHP berikut yang digunakan untuk mengunggah file:\\n\\n$target_dir = \\\"uploads/\\\";\\n$target_file = $target_dir . basename($_FILES[\\\"file\\\"][\\\"name\\\"]);\\nif (move_uploaded_file($_FILES[\\\"file\\\"][\\\"tmp_name\\\"], $target_file)) {\\n    echo \\\"File berhasil diunggah\\\";\\n} else {\\n    echo \\\"Gagal mengunggah\\\";\\n}\\n\\nJelaskan bug yang ada dan bagaimana cara memperbaikinya.\", \"explanation\": \"Kode tidak memeriksa tipe MIME atau ekstensi, sehingga file PHP berbahaya bisa diunggah dan diakses langsung.\"}, {\"answer\": \"Bug: Parameter userId langsung dimasukkan ke URL tanpa sanitasi, rentan terhadap SQL injection atau XSS jika data dari server tidak difilter. Selain itu, innerHTML dapat menyebabkan XSS jika data.content mengandung HTML berbahaya. Perbaikan: Gunakan parameterized queries di server, dan gunakan textContent atau sanitasi HTML sebelum dimasukkan ke DOM.\", \"question\": \"Kode JavaScript berikut melakukan request AJAX:\\n\\nfetch(\'/api/data?id=\' + userId)\\n  .then(response => response.json())\\n  .then(data => {\\n    document.getElementById(\'result\').innerHTML = data.content;\\n  });\\n\\nApa bug keamanan yang mungkin terjadi? Bagaimana cara memperbaikinya?\", \"explanation\": \"Penggunaan innerHTML dengan data dari server yang tidak tepercaya membuka celah XSS. Server juga harus memvalidasi input userId.\"}]', 'Fokus ke latihan mencari bug di kode ya', '2026-06-03 07:14:19'),
(19, 'Quv1ojcbZiS0QjT6IIsujK8rBWf1', 29, 'fokus ke framework js ya', 'SIA1', 'hard', 'mixed', 5, '[{\"answer\": \"Redux menggunakan store tunggal dengan reducer murni, aksi, dan middleware. Cocok untuk aplikasi besar dengan logika state kompleks. Vuex memiliki state, getters, mutations, dan actions; mutations sinkron, actions asinkron. Lebih terstruktur dan mudah dipelajari bagi developer Vue. NgRx mengadopsi pola Redux dengan RxJS, menggunakan store, actions, reducers, effects, dan selectors. Sangat cocok untuk aplikasi Angular yang sudah menggunakan observables. Kelebihan Redux: ekosistem luas dan devtools. Vuex: integrasi erat dengan Vue. NgRx: reaktif penuh dengan RxJS. Contoh: Redux untuk e-commerce, Vuex untuk dashboard real-time, NgRx untuk aplikasi data streaming.\", \"question\": \"Bandingkan pendekatan state management global antara React (Redux), Vue (Vuex), dan Angular (NgRx) dalam hal konsep inti, cara kerja, dan kelebihan masing-masing. Berikan contoh kasus penggunaan yang paling cocok untuk setiap framework.\", \"explanation\": \"Jawaban di atas merangkum perbedaan utama dan konteks penggunaan. Detail lebih lanjut dapat mencakup arsitektur dan trade-off.\"}, {\"answer\": \"Memudahkan berbagi state antar komponen saudara\", \"options\": [\"Mengurangi jumlah render yang tidak perlu\", \"Memudahkan berbagi state antar komponen saudara\", \"Meningkatkan kecepatan akses state melalui props\", \"Menghilangkan kebutuhan akan hooks seperti useState\"], \"question\": \"Dalam React, ketika state diangkat ke komponen induk (lifting state up), apa keuntungan utama yang diperoleh dibandingkan menyimpan state di komponen anak?\", \"explanation\": \"Lifting state up memungkinkan state dikelola di komponen induk dan dibagikan ke komponen anak melalui props, sehingga komponen saudara dapat berbagi data yang sama tanpa perlu menyimpan state redundan.\"}, {\"answer\": \"Computed bersifat sinkron dan otomatis di-cache, sedangkan watcher dapat digunakan untuk operasi asinkron\", \"options\": [\"Computed bersifat sinkron dan otomatis di-cache, sedangkan watcher dapat digunakan untuk operasi asinkron\", \"Computed hanya bisa digunakan di template, sedangkan watcher hanya di method\", \"Watcher lebih cepat daripada computed karena tidak perlu evaluasi ulang\", \"Computed dapat mengubah data secara langsung, sedangkan watcher hanya memantau\"], \"question\": \"Dalam Vue.js, apa perbedaan utama antara computed properties dan watchers dalam menangani perubahan data reaktif?\", \"explanation\": \"Computed properties di-cache berdasarkan dependensi reaktif dan hanya dievaluasi ulang saat dependensi berubah, cocok untuk transformasi data sinkron. Watchers memungkinkan eksekusi kustom (termasuk asinkron) saat properti tertentu berubah.\"}, {\"answer\": \"Dependency Injection dengan provider tree dan injektor hierarkis\", \"options\": [\"Dependency Injection dengan provider tree dan injektor hierarkis\", \"Props drilling dari komponen induk ke anak\", \"Global singleton melalui module root\", \"Context API seperti di React\"], \"question\": \"Dalam Angular, mekanisme apa yang digunakan untuk menyediakan dependensi ke komponen atau service secara hierarkis?\", \"explanation\": \"Angular menggunakan sistem DI di mana setiap komponen memiliki injektor sendiri yang dapat mewarisi dari induknya, memungkinkan penyediaan service pada level tertentu dan mengontrol lingkup instance.\"}, {\"answer\": \"React akan melewatkan re-render karena menggunakan Object.is untuk membandingkan nilai\", \"options\": [\"Komponen tetap di-render ulang karena setState selalu memicu re-render\", \"React akan melewatkan re-render karena menggunakan Object.is untuk membandingkan nilai\", \"Akan terjadi infinite loop karena perubahan state memicu render ulang\", \"State akan di-reset ke nilai awal komponen\"], \"question\": \"Dalam React, apa yang terjadi jika sebuah komponen memanggil setState dengan nilai yang sama dengan state saat ini (misalnya setState(count) di mana count tidak berubah)?\", \"explanation\": \"React melakukan shallow comparison (Object.is) terhadap state sebelumnya dan yang baru. Jika sama, React tidak akan memicu re-render pada komponen dan anak-anaknya, kecuali ada force update.\"}]', 'fokus ke framework js ya', '2026-06-03 07:25:45'),
(20, 'Quv1ojcbZiS0QjT6IIsujK8rBWf1', 29, 'Algoritma mesin learning', 'SIA1', 'medium', 'mixed', 5, '[{\"answer\": \"Memuat model di luar fungsi route, misalnya di level modul, agar model dimuat sekali saat server start\", \"options\": [\"Memuat model di dalam fungsi route setiap kali ada request untuk memastikan model selalu terbaru\", \"Memuat model di luar fungsi route, misalnya di level modul, agar model dimuat sekali saat server start\", \"Memuat model menggunakan `flask.request` agar model dapat diakses secara global\", \"Memuat model hanya saat endpoint `/predict` diakses dengan metode GET\"], \"question\": \"Dalam implementasi machine learning di web menggunakan Flask, langkah yang tepat untuk memuat model yang telah dilatih (misalnya model .pkl) agar siap digunakan pada request prediksi adalah...\", \"explanation\": \"Memuat model di luar route menghindari loading berulang yang memperlambat respons, cukup dimuat sekali saat aplikasi dijalankan.\"}, {\"answer\": \"NumPy dan Pandas\", \"options\": [\"Flask-WTF dan validasi data\", \"NumPy dan Pandas\", \"Scikit-learn dan Matplotlib\", \"JSON dan XML parser\"], \"question\": \"Saat menerima data input dari pengguna melalui form HTML di Flask untuk diproses oleh model machine learning, library yang paling umum digunakan untuk mengubah data tersebut menjadi array numerik yang siap dimasukkan ke model adalah...\", \"explanation\": \"NumPy dan Pandas menyediakan fungsi untuk mengonversi data mentah (misalnya dari request.form) menjadi array atau DataFrame yang kompatibel dengan model ML.\"}, {\"answer\": \"Menggunakan caching pada hasil prediksi yang sering diminta\", \"options\": [\"Menyimpan seluruh dataset training di dalam session Flask setiap pengguna\", \"Menggunakan caching pada hasil prediksi yang sering diminta\", \"Memuat ulang model dari file setiap kali ada request baru\", \"Menambahkan middleware untuk membatasi jumlah request per menit\"], \"question\": \"Seorang developer ingin membuat fitur rekomendasi sederhana di web menggunakan Flask dengan algoritma K-Nearest Neighbors (KNN). Langkah yang paling krusial agar model KNN dapat berjalan efisien saat diakses banyak pengguna secara bersamaan adalah...\", \"explanation\": \"KNN membutuhkan komputasi jarak yang bisa lambat untuk dataset besar. Caching mengurangi beban dengan menyimpan hasil prediksi yang sama untuk input serupa.\"}, {\"answer\": \"@app.route(\'/predict\', methods=[\'POST\'])\", \"options\": [\"@app.route(\'/predict\', methods=[\'GET\'])\", \"@app.route(\'/predict\', methods=[\'POST\'])\", \"@app.route(\'/predict\', methods=[\'PUT\'])\", \"@app.route(\'/predict\', methods=[\'DELETE\'])\"], \"question\": \"Dalam deployment model regresi linear menggunakan Flask, endpoint `/predict` menerima data JSON melalui metode POST. Agar server dapat memproses data tersebut, dekorator route yang tepat adalah...\", \"explanation\": \"Metode POST digunakan untuk mengirim data ke server, cocok untuk menerima input prediksi yang bersifat rahasia atau besar.\"}, {\"answer\": \"1. Simpan model yang telah dilatih dalam format file (misalnya .pkl menggunakan joblib atau pickle).\\n2. Buat aplikasi Flask dan muat model tersebut di luar fungsi route (global) agar hanya dimuat sekali.\\n3. Definisikan route (misalnya /predict) yang menerima data input dari pengguna (biasanya melalui metode POST dalam format JSON atau form).\\n4. Di dalam fungsi route, ekstrak data input, lakukan preprocessing jika diperlukan (misalnya scaling, encoding), lalu panggil model.predict(data).\\n5. Kembalikan hasil prediksi dalam format JSON (misalnya {\'prediction\': hasil}) beserta status code 200.\\n6. Tambahkan penanganan error (try-except) untuk input yang tidak valid.\", \"question\": \"Jelaskan secara singkat langkah-langkah yang perlu dilakukan untuk mengintegrasikan model machine learning (misalnya model klasifikasi yang sudah dilatih) ke dalam aplikasi web berbasis Flask, mulai dari persiapan model hingga pengembalian hasil prediksi ke pengguna.\", \"explanation\": \"Langkah-langkah ini memastikan model dapat diakses secara efisien dan memberikan respons yang sesuai kepada pengguna.\"}]', 'Algoritma mesin learning', '2026-06-03 07:28:48'),
(21, 'Quv1ojcbZiS0QjT6IIsujK8rBWf1', 29, 'Tes psikologi', 'SIA1', 'hard', 'multiple_choice', 5, '[{\"answer\": \"Perhitungan fungsi informasi item dan estimasi kemampuan memerlukan optimasi agar tidak membebani server, terutama saat banyak peserta bersamaan.\", \"options\": [\"Perhitungan fungsi informasi item dan estimasi kemampuan memerlukan optimasi agar tidak membebani server, terutama saat banyak peserta bersamaan.\", \"Model 3PL hanya dapat dihitung menggunakan library Python seperti PyIRT, sehingga harus di-deploy sebagai microservice terpisah.\", \"Parameter guessing (c) pada model 3PL tidak dapat diperbarui secara dinamis, sehingga CAT tidak efektif untuk tes psikologi.\", \"WebSocket diperlukan untuk mentransfer parameter item secara real-time, namun meningkatkan risiko kebocoran data soal.\"], \"question\": \"Dalam implementasi Computerized Adaptive Testing (CAT) berbasis web, algoritma Item Response Theory (IRT) digunakan untuk memilih soal berikutnya berdasarkan respons peserta. Manakah pernyataan yang PALING TEPAT mengenai tantangan utama dalam mengintegrasikan model IRT 3 parameter (3PL) ke dalam aplikasi web real-time?\", \"explanation\": \"Tantangan utama adalah kompleksitas komputasi estimasi Maximum Likelihood atau Bayesian yang harus dilakukan di sisi server dengan latensi rendah. Optimasi seperti caching, penggunaan Web Workers, atau algoritma aproksimasi diperlukan untuk menjaga performa.\"}, {\"answer\": \"Menggunakan anonimisasi data dengan memisahkan identitas peserta dari hasil tes, serta menyediakan API terbatas untuk akses peneliti.\", \"options\": [\"Mengenkripsi seluruh database dengan AES-256 dan memastikan kunci enkripsi disimpan di environment variable server.\", \"Menerapkan otentikasi dua faktor (2FA) untuk semua pengguna, termasuk peserta tes, agar data tidak diakses pihak tidak berwenang.\", \"Menggunakan anonimisasi data dengan memisahkan identitas peserta dari hasil tes, serta menyediakan API terbatas untuk akses peneliti.\", \"Menyimpan log akses ke data tes selama 5 tahun untuk kepatuhan audit, namun tanpa enkripsi end-to-end.\"], \"question\": \"Sebuah platform tes psikologi online menyimpan hasil tes dalam bentuk skor mentah dan profil kepribadian. Untuk memenuhi regulasi privasi data (seperti GDPR atau UU PDP Indonesia), langkah keamanan apa yang PALING KRITIS diterapkan pada arsitektur web?\", \"explanation\": \"Anonimisasi adalah prinsip utama privasi data. Meskipun enkripsi penting, anonimisasi mengurangi risiko jika terjadi kebocoran. API terbatas memastikan data sensitif hanya diakses sesuai izin.\"}, {\"answer\": \"Memanfaatkan Web Worker di sisi klien untuk melakukan kalkulasi skor secara paralel, lalu mengirim hasil ke server untuk validasi.\", \"options\": [\"Menggunakan AJAX synchronous (async: false) agar skor langsung diterima setelah setiap respons.\", \"Memanfaatkan Web Worker di sisi klien untuk melakukan kalkulasi skor secara paralel, lalu mengirim hasil ke server untuk validasi.\", \"Melakukan komputasi skor di server melalui endpoint REST yang dipanggil setiap kali peserta menjawab, dengan respons JSON berisi skor sementara.\", \"Menyimpan semua respons di localStorage dan menghitung skor saat tes selesai, lalu mengirim batch ke server.\"], \"question\": \"Dalam pengembangan aplikasi web untuk tes psikologi yang memerlukan skoring real-time, misalnya tes kecepatan persepsi, bagaimana cara paling efisien untuk menghitung skor dan memberikan feedback instan tanpa memblokir antarmuka pengguna?\", \"explanation\": \"Web Worker memungkinkan komputasi di latar belakang tanpa mengganggu UI. Ini penting untuk tes real-time di mana feedback cepat diperlukan. Server tetap perlu validasi untuk keamanan.\"}, {\"answer\": \"Membuat proxy server yang menerima data dari front-end, melakukan enkripsi ujung-ke-ujung, lalu meneruskannya ke API eksternal tanpa menyimpan log.\", \"options\": [\"Mengirim data respons langsung ke API eksternal dari front-end menggunakan Fetch API, sehingga server tidak menyimpan data mentah.\", \"Membuat proxy server yang menerima data dari front-end, melakukan enkripsi ujung-ke-ujung, lalu meneruskannya ke API eksternal tanpa menyimpan log.\", \"Menggunakan layanan API yang sudah memiliki sertifikasi ISO 27001 dan menandatangani perjanjian kerahasiaan data (NDA).\", \"Menganonimkan data respons dengan menghapus identifier pengguna sebelum dikirim ke API eksternal, serta membatasi frekuensi permintaan.\"], \"question\": \"Seorang pengembang ingin mengintegrasikan tes psikologi dengan layanan analisis sentimen berbasis AI melalui API eksternal. Manakah pendekatan yang PALING AMAN untuk menghindari kebocoran data respons peserta yang sensitif?\", \"explanation\": \"Proxy server dengan enkripsi end-to-end memastikan data tidak dapat dibaca oleh server sendiri. Tidak menyimpan log mencegah penyimpanan data sensitif. Anonimisasi juga penting, tetapi enkripsi memberikan lapisan keamanan tambahan.\"}, {\"answer\": \"Menggunakan WebSocket untuk komunikasi dua arah dan mengukur waktu reaksi di sisi klien dengan performance.now(), lalu mengirim hasilnya ke server.\", \"options\": [\"Menggunakan protokol HTTP/2 dengan server push untuk mempercepat pengiriman stimulus visual.\", \"Mengukur waktu reaksi di sisi server dengan mencatat timestamp saat stimulus dikirim dan respons diterima.\", \"Menggunakan WebSocket untuk komunikasi dua arah dan mengukur waktu reaksi di sisi klien dengan performance.now(), lalu mengirim hasilnya ke server.\", \"Melakukan kalibrasi latensi di awal sesi dengan mengirim ping dan menyesuaikan offset waktu pada setiap respons.\"], \"question\": \"Dalam merancang antarmuka web untuk tes psikologi yang mengukur respons waktu reaksi, latensi jaringan dapat memengaruhi validitas hasil. Teknik apa yang PALING EFEKTIF untuk meminimalkan dampak variasi latensi pada pengukuran waktu reaksi?\", \"explanation\": \"performance.now() memberikan resolusi tinggi dan tidak terpengaruh latensi jaringan. WebSocket memungkinkan pengiriman stimulus yang cepat. Mengukur di sisi klien lebih akurat daripada di server karena latensi tidak memengaruhi pengukuran.\"}]', 'Tes psikologi', '2026-06-04 14:38:41'),
(22, 'Quv1ojcbZiS0QjT6IIsujK8rBWf1', 29, 'UTS SEJARAH PENJAJAHAN BELANDA DI INDONESIA', 'SIA1', 'easy', 'multiple_choice', 5, '[{\"answer\": \"Cornelis de Houtman\", \"options\": [\"Cornelis de Houtman\", \"Herman Willem Daendels\", \"Johannes van den Bosch\", \"Thomas Stamford Raffles\"], \"question\": \"Siapa pemimpin ekspedisi Belanda pertama yang mendarat di Banten pada tahun 1596?\", \"explanation\": \"Ekspedisi Belanda pertama dipimpin oleh Cornelis de Houtman dan mendarat di Banten pada tahun 1596.\"}, {\"answer\": \"VOC\", \"options\": [\"VOC\", \"EIC\", \"Cultuurstelsel\", \"Politik Etis\"], \"question\": \"Apa nama kongsi dagang Belanda yang didirikan pada tahun 1602?\", \"explanation\": \"Vereenigde Oostindische Compagnie (VOC) didirikan pada tahun 1602 sebagai kongsi dagang Belanda.\"}, {\"answer\": \"31 Desember 1799\", \"options\": [\"31 Desember 1799\", \"8 Maret 1942\", \"27 Desember 1949\", \"1901\"], \"question\": \"Kapan VOC resmi dibubarkan?\", \"explanation\": \"VOC dibubarkan pada tanggal 31 Desember 1799 karena korupsi dan manajemen buruk.\"}, {\"answer\": \"Johannes van den Bosch\", \"options\": [\"Herman Willem Daendels\", \"Johannes van den Bosch\", \"Thomas Stamford Raffles\", \"Cornelis de Houtman\"], \"question\": \"Siapa Gubernur Jenderal yang menerapkan Sistem Tanam Paksa pada tahun 1830?\", \"explanation\": \"Johannes van den Bosch menerapkan Cultuurstelsel (Sistem Tanam Paksa) pada tahun 1830.\"}, {\"answer\": \"Perang Diponegoro\", \"options\": [\"Perang Padri\", \"Perang Diponegoro\", \"Perang Aceh\", \"Perang Bali\"], \"question\": \"Perlawanan besar terhadap Belanda di Jawa Tengah dan Yogyakarta pada tahun 1825-1830 dikenal sebagai?\", \"explanation\": \"Perang Diponegoro berlangsung dari tahun 1825 hingga 1830 dan merupakan perlawanan besar di Jawa Tengah dan Yogyakarta.\"}]', 'UTS SEJARAH PENJAJAHAN BELANDA DI INDONESIA', '2026-06-04 15:42:16');
INSERT INTO `questions` (`id`, `user_id`, `subject_id`, `title`, `class`, `difficulty`, `type`, `total_questions`, `questions_data`, `prompt_used`, `created_at`) VALUES
(23, 'Quv1ojcbZiS0QjT6IIsujK8rBWf1', 29, 'Algoritma mesin learning', 'SIA1', 'hard', 'multiple_choice', 5, '[{\"answer\": \"Huber loss mengurangi pengaruh outlier dengan menggabungkan sifat MSE dan MAE\", \"options\": [\"test\", \"Huber loss bersifat konveks sehingga menjamin optimasi global\", \"Huber loss mengurangi pengaruh outlier dengan menggabungkan sifat MSE dan MAE\", \"Huber loss menghasilkan estimasi yang tidak bias untuk distribusi normal\"], \"question\": \"Dalam algoritma Gradient Boosting, fungsi loss yang umum digunakan untuk regresi adalah Huber loss. Apa kelebihan utama Huber loss dibandingkan dengan Mean Squared Error (MSE) dalam konteks data dengan outlier?\", \"image_url\": null, \"explanation\": \"Huber loss bersifat robust terhadap outlier karena untuk residual kecil berperilaku seperti MSE (kuadratik) dan untuk residual besar berperilaku seperti MAE (linear), sehingga tidak memberikan bobot berlebihan pada outlier.\"}, {\"answer\": \"Setiap pohon memilih subset fitur secara acak pada setiap node split, biasanya sebanyak akar dari jumlah total fitur\", \"options\": [\"Setiap pohon menggunakan semua fitur yang ada, namun dengan bobot yang berbeda\", \"Setiap pohon memilih subset fitur secara acak pada setiap node split, biasanya sebanyak akar dari jumlah total fitur\", \"Setiap pohon hanya menggunakan fitur dengan korelasi tinggi terhadap target\", \"Setiap pohon menggunakan fitur yang sama, tetapi dengan urutan split yang diacak\"], \"question\": \"Dalam Random Forest, bagaimana cara kerja proses pemilihan fitur pada setiap split pohon untuk memaksimalkan diversitas antar pohon?\", \"explanation\": \"Random Forest menggunakan metode bagging dan random subspace. Pada setiap node split, hanya subset fitur yang dipertimbangkan (biasanya sqrt(p) untuk klasifikasi), sehingga menghasilkan pohon yang beragam dan mengurangi overfitting.\"}, {\"answer\": \"Model menjadi sangat sensitif terhadap titik data individu, sehingga dapat menyebabkan overfitting\", \"options\": [\"Model menjadi lebih sederhana dan cenderung underfitting\", \"Model menjadi sangat sensitif terhadap titik data individu, sehingga dapat menyebabkan overfitting\", \"Model menjadi tidak sensitif terhadap jarak antar titik data\", \"Model mengabaikan fungsi kernel dan berperilaku seperti SVM linear\"], \"question\": \"Dalam Support Vector Machine (SVM) dengan kernel RBF (Radial Basis Function), parameter gamma mengontrol pengaruh dari setiap titik data. Apa yang terjadi jika nilai gamma sangat besar?\", \"explanation\": \"Gamma besar membuat kurva Gaussian menjadi sempit, sehingga hanya titik data yang sangat dekat yang mempengaruhi decision boundary. Akibatnya, model menangkap noise dan overfit.\"}, {\"answer\": \"Metode Elbow mengasumsikan cluster berbentuk spherical dan berukuran sama, sehingga tidak cocok untuk data dengan variasi kepadatan\", \"options\": [\"Metode Elbow tidak dapat digunakan jika data memiliki dimensi tinggi\", \"Metode Elbow cenderung memilih jumlah cluster yang terlalu sedikit karena kurva tidak menunjukkan siku yang jelas\", \"Metode Elbow mengasumsikan cluster berbentuk spherical dan berukuran sama, sehingga tidak cocok untuk data dengan variasi kepadatan\", \"Metode Elbow hanya bekerja untuk data yang telah dinormalisasi\"], \"question\": \"Dalam algoritma K-Means, metode Elbow digunakan untuk menentukan jumlah cluster optimal. Namun, metode ini memiliki kelemahan utama ketika data memiliki cluster dengan kepadatan yang tidak seragam. Manakah dari berikut yang merupakan kelemahan tersebut?\", \"explanation\": \"K-Means menggunakan jarak Euclidean dan meminimalkan inertia (jumlah kuadrat jarak dalam cluster). Jika cluster memiliki kepadatan berbeda, inertia tidak akan menurun secara monoton yang jelas, sehingga siku sulit diidentifikasi.\"}, {\"answer\": \"Menggunakan varian ReLU seperti Leaky ReLU atau Parametric ReLU\", \"options\": [\"Menggunakan fungsi aktivasi sigmoid sebagai pengganti ReLU\", \"Menerapkan batch normalization sebelum setiap layer\", \"Menggunakan varian ReLU seperti Leaky ReLU atau Parametric ReLU\", \"Menambahkan dropout layer setelah aktivasi ReLU\"], \"question\": \"Dalam jaringan saraf tiruan (neural network) untuk klasifikasi, fungsi aktivasi ReLU (Rectified Linear Unit) sering digunakan di hidden layer. Namun, ReLU memiliki masalah \'dying ReLU\' di mana neuron menjadi tidak aktif. Manakah dari teknik berikut yang paling efektif untuk mengatasi masalah tersebut?\", \"explanation\": \"Leaky ReLU memberikan gradien kecil untuk input negatif (misal 0.01x), sehingga neuron tetap dapat memperbarui bobot meskipun input negatif. Parametric ReLU mempelajari parameter kemiringan negatif secara otomatis.\"}]', 'Algoritma mesin learning', '2026-06-04 16:54:37'),
(24, 'Quv1ojcbZiS0QjT6IIsujK8rBWf1', 29, 'fokus ke framework js ya', 'SIA1', 'hard', 'multiple_choice', 5, '[{\"answer\": \"Tidak ada re-render, perubahan akan hilang pada render berikutnya\", \"options\": [\"Komponen akan langsung re-render dengan nilai baru\", \"Tidak ada re-render, perubahan akan hilang pada render berikutnya\", \"React akan mengabaikan perubahan dan memicu error\", \"State akan berubah tetapi komponen tidak akan re-render\"], \"question\": \"Dalam React, jika Anda mengubah state secara langsung (misal: this.state.count = 5) tanpa menggunakan setState, apa yang akan terjadi?\", \"image_url\": \"/public/assets/question/images/q_1780673381_7c818843.png\", \"explanation\": \"React tidak akan mendeteksi mutasi langsung pada state. Saat setState dipanggil, React akan membandingkan state lama dan baru untuk memicu re-render. Mutasi langsung tidak memicu perbandingan, sehingga perubahan akan ditimpa saat render berikutnya.\"}, {\"answer\": \"Properti baru tidak reaktif, perlu menggunakan Vue.set()\", \"options\": [\"Properti baru secara otomatis menjadi reaktif karena Vue menggunakan Proxy\", \"Properti baru tidak reaktif, perlu menggunakan Vue.set()\", \"Properti baru akan reaktif hanya jika dideklarasikan di data\", \"Properti baru akan memicu error karena tidak bisa ditambahkan\"], \"question\": \"Di Vue.js 2, bagaimana cara kerja reaktivitas pada properti objek yang ditambahkan setelah inisialisasi (misal: this.obj.newProp = \'value\')?\", \"explanation\": \"Vue 2 menggunakan Object.defineProperty untuk melacak perubahan, sehingga hanya properti yang sudah ada saat inisialisasi yang reaktif. Untuk menambahkan properti baru secara reaktif, harus menggunakan Vue.set() atau this.$set().\"}, {\"answer\": \"OnPush hanya mengecek perubahan saat input binding berubah atau event terjadi, Default mengecek setiap perubahan di seluruh komponen\", \"options\": [\"OnPush hanya mengecek perubahan saat event terjadi, Default mengecek setiap perubahan data\", \"Default menonaktifkan deteksi perubahan, OnPush mengaktifkannya\", \"OnPush hanya mengecek perubahan saat input binding berubah atau event terjadi, Default mengecek setiap perubahan di seluruh komponen\", \"Default lebih cepat karena tidak menggunakan zone.js\"], \"question\": \"Di Angular, apa perbedaan utama antara ChangeDetectionStrategy.Default dan ChangeDetectionStrategy.OnPush?\", \"explanation\": \"Dengan Default, Angular menggunakan zone.js untuk mendeteksi perubahan secara otomatis (misal: setTimeout, HTTP). OnPush membatasi deteksi hanya ketika input reference berubah (immutable) atau event dari komponen itu sendiri, sehingga lebih optimal.\"}, {\"answer\": \"Svelte mengkompilasi komponen menjadi kode imperatif yang langsung memanipulasi DOM, React menggunakan diffing virtual DOM di runtime\", \"options\": [\"Svelte menggunakan virtual DOM di runtime, React menggunakan kompilasi\", \"Svelte mengkompilasi komponen menjadi kode imperatif yang langsung memanipulasi DOM, React menggunakan diffing virtual DOM di runtime\", \"Svelte menggunakan Proxy untuk reaktivitas, React menggunakan Object.defineProperty\", \"Svelte dan React sama-sama menggunakan virtual DOM, hanya sintaks yang berbeda\"], \"question\": \"Di Svelte, bagaimana compiler menangani reaktivitas dibandingkan dengan framework berbasis virtual DOM seperti React?\", \"explanation\": \"Svelte adalah compiler yang mengubah komponen menjadi kode JavaScript murni saat build time, sehingga tidak perlu virtual DOM. React menggunakan virtual DOM untuk menghitung perubahan dan memperbarui DOM secara efisien di runtime.\"}, {\"answer\": \"getStaticProps mengambil data saat build time untuk static generation, getServerSideProps mengambil data setiap request untuk server-side rendering\", \"options\": [\"getStaticProps mengambil data saat runtime setiap request, getServerSideProps mengambil data saat build time\", \"getStaticProps mengambil data saat build time untuk static generation, getServerSideProps mengambil data setiap request untuk server-side rendering\", \"getStaticProps hanya untuk halaman statis, getServerSideProps untuk halaman dinamis tanpa caching\", \"getStaticProps dan getServerSideProps sama-sama mengambil data saat build time\"], \"question\": \"Di Next.js (framework React), apa perbedaan antara getStaticProps dan getServerSideProps dalam hal kapan data diambil dan bagaimana halaman dirender?\", \"explanation\": \"getStaticProps digunakan untuk Static Site Generation (SSG) di mana data diambil sekali saat build dan halaman di-cache. getServerSideProps digunakan untuk Server-Side Rendering (SSR) di mana data diambil setiap kali ada request, sehingga halaman selalu fresh.\"}]', 'fokus ke framework js ya', '2026-06-05 15:16:49'),
(25, 'Quv1ojcbZiS0QjT6IIsujK8rBWf1', 29, 'Fiqih Siyasah', 'SIA1', 'hard', 'multiple_choice', 5, '[{\"answer\": \"Harus terdiri dari para ulama dan cendekiawan yang memiliki kapasitas ijtihad dan keadilan.\", \"options\": [\"Harus terdiri dari para ulama dan cendekiawan yang memiliki kapasitas ijtihad dan keadilan.\", \"Hanya terdiri dari para pemimpin suku dan panglima militer.\", \"Anggota dipilih langsung oleh rakyat melalui pemilu bebas.\", \"Semua warga negara yang telah baligh dan berakal sehat berhak menjadi anggota.\"], \"question\": \"Dalam teori Fiqih Siyasah, konsep \'Ahl al-Hall wa al-Aqd\' memiliki wewenang untuk memilih dan memberhentikan khalifah. Namun, terdapat perbedaan pendapat mengenai syarat keanggotaan lembaga ini. Manakah pernyataan berikut yang paling tepat menggambarkan pandangan mayoritas ulama klasik tentang syarat anggota Ahl al-Hall wa al-Aqd?\", \"explanation\": \"Mayoritas ulama klasik seperti Al-Mawardi dan Al-Ghazali mensyaratkan anggota Ahl al-Hall wa al-Aqd memiliki sifat adil, berilmu, dan mampu berijtihad, sehingga tidak sembarang orang bisa menjadi anggota.\"}, {\"answer\": \"Memberikan nasihat terlebih dahulu, jika tidak diindahkan maka dapat dicabut bai\'atnya melalui musyawarah.\", \"options\": [\"Langsung memberhentikan khalifah tanpa melalui proses musyawarah.\", \"Memberikan nasihat terlebih dahulu, jika tidak diindahkan maka dapat dicabut bai\'atnya melalui musyawarah.\", \"Menyerahkan keputusan kepada rakyat melalui referendum.\", \"Membiarkan karena bai\'at bersifat mutlak dan tidak dapat dicabut.\"], \"question\": \"Konsep \'bai\'at\' dalam Fiqih Siyasah tidak hanya bersifat simbolis, tetapi memiliki implikasi hukum yang mengikat. Dalam situasi khalifah melakukan pelanggaran syariat secara terang-terangan, mekanisme apa yang dapat dilakukan oleh Ahl al-Hall wa al-Aqd berdasarkan prinsip amar ma\'ruf nahi munkar?\", \"explanation\": \"Menurut Jumhur ulama, pencabutan bai\'at tidak boleh dilakukan secara sepihak, tetapi melalui proses nasihat dan musyawarah Ahl al-Hall wa al-Aqd, karena bai\'at adalah kontrak yang mengikat kedua belah pihak.\"}, {\"answer\": \"Wilayah al-mazalim memiliki kewenangan yang lebih luas termasuk mengadili pejabat negara, sedangkan qadha terbatas pada sengketa antar rakyat.\", \"options\": [\"Wilayah al-mazalim hanya menangani kasus pidana berat, sedangkan qadha menangani kasus perdata.\", \"Wilayah al-mazalim memiliki kewenangan yang lebih luas termasuk mengadili pejabat negara, sedangkan qadha terbatas pada sengketa antar rakyat.\", \"Wilayah al-mazalim tidak memerlukan saksi, sedangkan qadha memerlukan saksi.\", \"Qadha bersifat independen, sedangkan wilayah al-mazalim berada di bawah kendali khalifah.\"], \"question\": \"Dalam Fiqih Siyasah, konsep \'wilayah al-mazalim\' (pengadilan kezaliman) memiliki peran penting dalam mengawasi kebijakan penguasa. Namun, terdapat perdebatan tentang hubungannya dengan peradilan biasa (qadha). Manakah pernyataan yang paling akurat mengenai perbedaan mendasar antara qadha dan wilayah al-mazalim menurut Al-Mawardi?\", \"explanation\": \"Al-Mawardi dalam Al-Ahkam al-Sultaniyyah menjelaskan bahwa wilayah al-mazalim menangani pengaduan terhadap pejabat negara, penyalahgunaan kekuasaan, dan kasus-kasus yang tidak tertangani oleh qadha biasa.\"}, {\"answer\": \"Hasil syura mengikat selama tidak bertentangan dengan nash, dan khalifah wajib melaksanakannya.\", \"options\": [\"Hasil syura bersifat mutlak mengikat dan tidak dapat dibatalkan oleh khalifah.\", \"Syura hanya sebagai formalitas, keputusan akhir tetap di tangan khalifah.\", \"Hasil syura mengikat selama tidak bertentangan dengan nash, dan khalifah wajib melaksanakannya.\", \"Syura hanya berlaku dalam masalah ijtihadiyah, sedangkan masalah qath\'iy tidak perlu dimusyawarahkan.\"], \"question\": \"Dalam sistem ketatanegaraan Islam, konsep \'syura\' sering diartikan sebagai musyawarah. Namun, terdapat perbedaan penafsiran mengenai apakah hasil syura bersifat mengikat atau hanya sebagai pertimbangan. Manakah pandangan yang paling sesuai dengan prinsip Fiqih Siyasah yang dikembangkan oleh para sahabat pada masa Khulafaur Rasyidin?\", \"explanation\": \"Praktik Khulafaur Rasyidin menunjukkan bahwa syura adalah mekanisme pengambilan keputusan kolektif yang mengikat, namun tetap dalam kerangka syariat. Contohnya dalam pemilihan Abu Bakar dan Umar, hasil syura diikuti oleh seluruh kaum muslimin.\"}, {\"answer\": \"Darurah harus bersifat sementara, proporsional, dan tidak melampaui batas kebutuhan, serta tidak boleh menimbulkan kerusakan yang lebih besar.\", \"options\": [\"Darurah dapat diterapkan kapan saja demi kemaslahatan umum, meskipun bertentangan dengan nash.\", \"Darurah hanya berlaku untuk masalah ibadah, tidak untuk masalah politik.\", \"Darurah harus bersifat sementara, proporsional, dan tidak melampaui batas kebutuhan, serta tidak boleh menimbulkan kerusakan yang lebih besar.\", \"Keputusan darurat sepenuhnya berada di tangan penguasa tanpa perlu pertimbangan ulama.\"], \"question\": \"Konsep \'darurah\' (kondisi darurat) dalam Fiqih Siyasah sering digunakan untuk membenarkan kebijakan penguasa yang menyimpang dari ketentuan normal. Namun, para ulama menetapkan batasan ketat agar tidak disalahgunakan. Manakah pernyataan berikut yang paling tepat menggambarkan batasan penerapan darurah dalam konteks politik?\", \"explanation\": \"Kaedah fiqh menyatakan \'ad-daruraat tubihu al-mahzuraat\' (kondisi darurat membolehkan yang dilarang), namun ulama menekankan bahwa darurah harus diukur secara ketat, tidak boleh dijadikan alasan permanen, dan harus dihentikan segera setelah kondisi normal.\"}]', 'Fiqih Siyasah', '2026-06-06 03:36:36'),
(26, 'V0pHPx3UHgUjpjqowQ9Iay0SZHG2', 32, 'fokus ke framework js ya', '12 SMA', 'medium', 'multiple_choice', 5, '[{\"answer\": \"Kerangka hukum dan kebijakan yang mengatur penyelenggaraan jaminan sosial bagi seluruh warga negara\", \"options\": [\"Kerangka hukum dan kebijakan yang mengatur penyelenggaraan jaminan sosial bagi seluruh warga negara\", \"Program bantuan langsung tunai yang diberikan kepada masyarakat miskin\", \"Sistem asuransi kesehatan swasta yang dikelola oleh perusahaan asuransi\", \"Kumpulan peraturan daerah tentang kesejahteraan sosial\"], \"question\": \"Apa yang dimaksud dengan Framework Jaminan Sosial (JS) dalam konteks sistem perlindungan sosial di Indonesia?\", \"explanation\": \"Framework Jaminan Sosial (JS) adalah kerangka hukum dan kebijakan yang menjadi landasan penyelenggaraan jaminan sosial, termasuk BPJS Kesehatan dan BPJS Ketenagakerjaan, yang bertujuan melindungi seluruh warga negara.\"}, {\"answer\": \"UU No. 40 Tahun 2004 tentang Sistem Jaminan Sosial Nasional\", \"options\": [\"UU No. 40 Tahun 2004 tentang Sistem Jaminan Sosial Nasional\", \"UU No. 36 Tahun 2009 tentang Kesehatan\", \"UU No. 13 Tahun 2003 tentang Ketenagakerjaan\", \"UU No. 11 Tahun 2009 tentang Kesejahteraan Sosial\"], \"question\": \"Undang-Undang apa yang menjadi dasar utama Framework Jaminan Sosial (JS) di Indonesia?\", \"explanation\": \"UU No. 40 Tahun 2004 tentang Sistem Jaminan Sosial Nasional (SJSN) merupakan landasan hukum utama yang membentuk framework jaminan sosial di Indonesia.\"}, {\"answer\": \"Iuran peserta yang dikelola secara bersama untuk menanggung risiko sosial\", \"options\": [\"Iuran peserta yang dikelola secara bersama untuk menanggung risiko sosial\", \"Pembayaran tunai langsung dari pemerintah kepada peserta\", \"Subsidi silang dari peserta kaya ke peserta miskin melalui pajak\", \"Asuransi komersial yang memberikan keuntungan bagi perusahaan\"], \"question\": \"Dalam Framework Jaminan Sosial (JS), prinsip gotong royong diterapkan melalui mekanisme apa?\", \"explanation\": \"Prinsip gotong royong dalam framework JS berarti iuran dari seluruh peserta dikumpulkan dan digunakan untuk membayar manfaat bagi peserta yang membutuhkan, mencerminkan solidaritas sosial.\"}, {\"answer\": \"Seluruh warga negara Indonesia tanpa terkecuali\", \"options\": [\"Seluruh warga negara Indonesia tanpa terkecuali\", \"Hanya pekerja formal di sektor swasta\", \"Warga negara yang mampu membayar iuran saja\", \"Pegawai negeri sipil dan anggota TNI/Polri\"], \"question\": \"Siapa saja yang menjadi peserta dalam Framework Jaminan Sosial (JS) menurut UU SJSN?\", \"explanation\": \"Framework JS bersifat universal, mencakup seluruh warga negara, baik pekerja formal, informal, maupun tidak bekerja, meskipun implementasinya bertahap.\"}, {\"answer\": \"Kurangnya partisipasi pekerja informal karena keterbatasan kesadaran dan kemampuan membayar iuran\", \"options\": [\"Kurangnya partisipasi pekerja informal karena keterbatasan kesadaran dan kemampuan membayar iuran\", \"Tidak adanya regulasi yang mengatur jaminan sosial\", \"Semua warga negara sudah terdaftar secara otomatis\", \"Dana jaminan sosial yang berlebihan sehingga tidak perlu iuran\"], \"question\": \"Apa tantangan utama dalam implementasi Framework Jaminan Sosial (JS) di Indonesia saat ini?\", \"explanation\": \"Pekerja informal sulit dijangkau dan seringkali tidak mampu membayar iuran, sehingga menjadi tantangan besar dalam perluasan cakupan JS.\"}]', 'fokus ke framework js ya', '2026-06-06 07:06:33'),
(27, 'V0pHPx3UHgUjpjqowQ9Iay0SZHG2', 32, 'Ujian Akhir Semester', '12 SMA', 'hard', 'multiple_choice', 5, '[{\"answer\": \"Majelis Permusyawaratan Rakyat (MPR)\", \"options\": [\"Majelis Permusyawaratan Rakyat (MPR)\", \"Dewan Perwakilan Rakyat (DPR)\", \"Presiden bersama DPR\", \"Mahkamah Konstitusi (MK)\"], \"question\": \"Dalam sistem ketatanegaraan Indonesia pasca-amandemen UUD 1945, lembaga negara yang memiliki kewenangan untuk mengubah dan menetapkan Undang-Undang Dasar adalah...\", \"explanation\": \"Berdasarkan Pasal 3 UUD 1945, MPR berwenang mengubah dan menetapkan UUD. DPR, Presiden, dan MK tidak memiliki kewenangan tersebut.\"}, {\"answer\": \"Mengedepankan musyawarah untuk mufakat sebelum pemungutan suara\", \"options\": [\"Penggunaan sistem voting mayoritas mutlak dalam setiap rapat\", \"Mengedepankan musyawarah untuk mufakat sebelum pemungutan suara\", \"Kebebasan mutlak anggota parlemen tanpa batasan fraksi\", \"Pengambilan keputusan oleh pimpinan lembaga tanpa diskusi\"], \"question\": \"Prinsip demokrasi Pancasila menekankan keseimbangan antara kebebasan individu dan kepentingan bersama. Implementasi prinsip ini dalam pengambilan keputusan di lembaga perwakilan tercermin dalam...\", \"explanation\": \"Demokrasi Pancasila mengutamakan musyawarah untuk mencapai mufakat sebagai ciri khas, bukan voting mayoritas mutlak atau kebebasan tanpa batas.\"}, {\"answer\": \"Adanya otonomi seluas-luasnya bagi daerah kecuali urusan yang ditetapkan sebagai urusan pusat\", \"options\": [\"Pemerintah pusat dapat membubarkan daerah otonom jika dianggap gagal\", \"Daerah memiliki kewenangan penuh dalam semua urusan pemerintahan\", \"Adanya otonomi seluas-luasnya bagi daerah kecuali urusan yang ditetapkan sebagai urusan pusat\", \"Gubernur sebagai wakil pemerintah pusat tidak memiliki wewenang mengawasi daerah\"], \"question\": \"Dalam kerangka Negara Kesatuan Republik Indonesia, hubungan antara pemerintah pusat dan daerah diatur dengan prinsip desentralisasi, dekonsentrasi, dan tugas pembantuan. Salah satu konsekuensi dari desentralisasi adalah...\", \"explanation\": \"Pasal 18 UUD 1945 dan UU Pemerintahan Daerah memberikan otonomi seluas-luasnya, namun urusan tertentu (misal politik luar negeri, pertahanan) tetap menjadi kewenangan pusat.\"}, {\"answer\": \"Pasal 28D ayat (1)\", \"options\": [\"Pasal 27 ayat (1)\", \"Pasal 28D ayat (1)\", \"Pasal 28I ayat (1)\", \"Pasal 34 ayat (2)\"], \"question\": \"Hak warga negara untuk didampingi penasihat hukum selama proses peradilan dijamin dalam UUD 1945. Ketentuan ini secara spesifik tercantum dalam...\", \"explanation\": \"Pasal 28D ayat (1) UUD 1945 menyatakan setiap orang berhak atas pengakuan, jaminan, perlindungan, dan kepastian hukum yang adil serta perlakuan yang sama di hadapan hukum, yang mencakup hak atas bantuan hukum.\"}, {\"answer\": \"Pembukaan UUD 1945 alinea keempat yang menyerukan perdamaian dunia\", \"options\": [\"Pasal 11 UUD 1945 tentang perjanjian internasional\", \"Pasal 13 UUD 1945 tentang kewenangan presiden dalam hubungan luar negeri\", \"Pembukaan UUD 1945 alinea keempat yang menyerukan perdamaian dunia\", \"Pasal 30 UUD 1945 tentang pertahanan dan keamanan negara\"], \"question\": \"Dalam politik luar negeri Indonesia yang bebas aktif, partisipasi dalam misi pemeliharaan perdamaian PBB merupakan bentuk implementasi dari...\", \"explanation\": \"Pembukaan UUD 1945 alinea keempat menyatakan tujuan negara ikut melaksanakan ketertiban dunia berdasarkan kemerdekaan, perdamaian abadi, dan keadilan sosial, yang mendasari partisipasi Indonesia dalam misi perdamaian PBB.\"}]', 'Ujian Akhir Semester', '2026-06-06 07:54:57'),
(28, 'Quv1ojcbZiS0QjT6IIsujK8rBWf1', 29, 'UAS', 'SIA1', 'hard', 'multiple_choice', 5, '[{\"answer\": \"IoC membalikkan kontrol pembuatan objek dari kelas pengguna ke container, sehingga dependency dikelola secara otomatis dan dapat diganti dengan mudah.\", \"options\": [\"IoC memungkinkan controller untuk langsung menginstansiasi dependency-nya sendiri tanpa bantuan container.\", \"IoC membalikkan kontrol pembuatan objek dari kelas pengguna ke container, sehingga dependency dikelola secara otomatis dan dapat diganti dengan mudah.\", \"IoC hanya digunakan pada tahap routing, bukan pada pembuatan objek service atau repository.\", \"IoC mengharuskan semua dependency didefinisikan dalam file konfigurasi statis agar container dapat bekerja.\"], \"question\": \"Dalam arsitektur framework MVC, konsep Inversion of Control (IoC) sering diimplementasikan melalui Dependency Injection (DI). Manakah pernyataan yang PALING TEPAT mengenai peran IoC dalam framework seperti Laravel?\", \"explanation\": \"IoC adalah prinsip di mana kontrol pembuatan objek dialihkan ke container (misalnya Laravel\'s service container), memungkinkan dependency injection secara otomatis dan memudahkan penggantian implementasi tanpa mengubah kode pengguna.\"}, {\"answer\": \"Membuat middleware khusus yang memeriksa peran pengguna dan mengembalikan response 403 jika tidak sesuai, lalu mendaftarkannya pada grup route yang membutuhkan peran tersebut.\", \"options\": [\"Mendefinisikan middleware di route dan mengecek peran pengguna di dalam controller setelah middleware berjalan.\", \"Membuat middleware khusus yang memeriksa peran pengguna dan mengembalikan response 403 jika tidak sesuai, lalu mendaftarkannya pada grup route yang membutuhkan peran tersebut.\", \"Menggunakan middleware global yang mengecek peran setiap request tanpa terkecuali.\", \"Menambahkan pengecekan peran langsung di dalam method `handle` dari middleware default `auth`.\"], \"question\": \"Dalam framework Laravel, middleware dapat digunakan untuk memfilter request sebelum mencapai controller. Manakah skenario yang menunjukkan penggunaan middleware yang PALING TEPAT untuk menangani autentikasi berbasis peran (role-based)?\", \"explanation\": \"Middleware khusus untuk role-based lebih modular dan dapat diterapkan hanya pada route tertentu. Ini memisahkan logika otorisasi dari controller dan memungkinkan reuse serta pengujian yang lebih baik.\"}, {\"answer\": \"Sebuah tabel \'posts\' dan \'videos\' yang sama-sama memiliki banyak \'comments\', di mana \'comments\' dapat dimiliki oleh \'posts\' dan \'videos\' melalui tabel pivot \'commentables\'.\", \"options\": [\"Sebuah tabel \'posts\' dan \'videos\' yang sama-sama memiliki banyak \'comments\', di mana \'comments\' dapat dimiliki oleh \'posts\' dan \'videos\' melalui tabel pivot \'commentables\'.\", \"Sebuah tabel \'users\' yang memiliki satu \'profile\' dan satu \'address\', di mana \'profile\' dan \'address\' tidak memiliki hubungan dengan model lain.\", \"Sebuah tabel \'orders\' yang berelasi dengan \'products\' melalui tabel \'order_product\', di mana \'products\' hanya digunakan oleh \'orders\'.\", \"Sebuah tabel \'roles\' yang dimiliki oleh banyak \'users\' dan \'permissions\' yang dimiliki oleh banyak \'roles\' melalui tabel pivot \'role_user\' dan \'permission_role\'.\"], \"question\": \"Dalam Eloquent ORM (Laravel), relasi polimorfik memungkinkan sebuah model terhubung dengan beberapa model lain dalam satu asosiasi. Manakah contoh penggunaan yang PALING TEPAT untuk relasi polimorfik many-to-many?\", \"explanation\": \"Relasi polimorfik many-to-many menggunakan tabel pivot dengan kolom morphable type dan id, memungkinkan satu model (misal Comment) terhubung ke banyak model lain (Post dan Video) melalui satu tabel perantara.\"}, {\"answer\": \"Service Provider digunakan untuk mendaftarkan service ke container, sedangkan Facade menyediakan antarmuka statis untuk mengakses service tersebut tanpa perlu injeksi manual.\", \"options\": [\"Service Provider digunakan untuk mendaftarkan service ke container, sedangkan Facade menyediakan antarmuka statis untuk mengakses service tersebut tanpa perlu injeksi manual.\", \"Service Provider dan Facade memiliki fungsi yang sama, hanya berbeda dalam penamaan.\", \"Facade digunakan untuk mendaftarkan service, sedangkan Service Provider digunakan untuk mengakses service secara statis.\", \"Service Provider hanya dapat digunakan untuk service bawaan framework, sedangkan Facade hanya untuk service pihak ketiga.\"], \"question\": \"Dalam framework Laravel, fitur Service Provider dan Facade digunakan untuk mengelola dan mengakses service container. Manakah pernyataan yang PALING TEPAT mengenai perbedaan antara Service Provider dan Facade?\", \"explanation\": \"Service Provider adalah tempat untuk mendaftarkan binding, event listener, middleware, dan konfigurasi ke container. Facade adalah alias statis yang memungkinkan akses cepat ke instance service yang terdaftar di container tanpa harus melakukan resolusi manual.\"}, {\"answer\": \"Middleware dieksekusi sebelum request mencapai controller, dan dapat menghentikan request dengan mengembalikan response lebih awal.\", \"options\": [\"Middleware dieksekusi setelah controller selesai memproses request, sehingga dapat memodifikasi response.\", \"Middleware dieksekusi sebelum request mencapai controller, dan dapat menghentikan request dengan mengembalikan response lebih awal.\", \"Middleware hanya dieksekusi untuk route yang memiliki parameter middleware di definisi route, dan tidak dapat dihentikan di tengah.\", \"Middleware dieksekusi secara acak tergantung pada prioritas yang ditentukan di kernel.\"], \"question\": \"Dalam pengembangan framework web, konsep \'middleware\' sering digunakan untuk menangani cross-cutting concerns. Manakah pernyataan yang PALING TEPAT mengenai urutan eksekusi middleware dalam sebuah framework seperti Laravel?\", \"explanation\": \"Middleware berfungsi sebagai lapisan filter yang dijalankan sebelum request masuk ke controller. Jika middleware mengembalikan response (misal redirect atau error), request tidak akan dilanjutkan ke controller. Urutan eksekusi ditentukan oleh prioritas dan grup middleware.\"}]', 'UAS', '2026-06-07 05:10:47'),
(29, 'Quv1ojcbZiS0QjT6IIsujK8rBWf1', 29, 'Variable Di Php', 'SIA1', 'hard', 'multiple_choice', 5, '[{\"answer\": \"$nama = \'Andi\';\", \"options\": [\"var $nama = \'Andi\';\", \"$nama = \'Andi\';\", \"int $nama = \'Andi\';\", \"dim $nama = \'Andi\';\"], \"question\": \"Manakah cara yang benar untuk mendeklarasikan variable di PHP?\", \"explanation\": \"Di PHP, variable dideklarasikan dengan tanda $ diikuti nama variable, tanpa kata kunci khusus. Opsi lain menggunakan sintaks dari bahasa lain.\"}, {\"answer\": \"15\", \"options\": [\"105\", \"15\", \"Error\", \"10\"], \"question\": \"Apa hasil dari kode berikut: $a = \'10\'; $b = 5; echo $a + $b; ?\", \"explanation\": \"PHP secara otomatis mengkonversi string \'10\' menjadi integer saat operasi aritmatika, sehingga hasilnya 10 + 5 = 15.\"}, {\"answer\": \"$nama_saya\", \"options\": [\"$2nama\", \"$nama_saya\", \"$nama-saya\", \"$nama saya\"], \"question\": \"Manakah nama variable yang valid di PHP?\", \"explanation\": \"Nama variable PHP harus diawali dengan huruf atau underscore, dan hanya boleh mengandung huruf, angka, dan underscore. Tanda hubung dan spasi tidak diperbolehkan.\"}, {\"answer\": \"Mengecek apakah variable ada dan tidak null, lalu mengembalikan nilainya, jika null maka mengembalikan nilai default\", \"options\": [\"Mengecek apakah variable ada dan tidak null, lalu mengembalikan nilainya, jika null maka mengembalikan nilai default\", \"Membandingkan dua variable apakah sama\", \"Menggabungkan dua string\", \"Menambahkan nilai ke variable\"], \"question\": \"Apa fungsi dari operator \'??\' (null coalescing) pada PHP?\", \"explanation\": \"Operator ?? mengembalikan nilai kiri jika tidak null dan terdefinisi, jika tidak maka mengembalikan nilai kanan. Contoh: $nama = $user ?? \'Tamu\';\"}, {\"answer\": \"define(\'NAMA\', \'Andi\');\", \"options\": [\"define(\'NAMA\', \'Andi\');\", \"$NAMA = \'Andi\';\", \"const NAMA = \'Andi\';\", \"constant(\'NAMA\', \'Andi\');\"], \"question\": \"Bagaimana cara mendefinisikan konstanta di PHP?\", \"explanation\": \"Konstanta dapat didefinisikan dengan fungsi define() atau keyword const (di luar class). Namun define() lebih umum dan dapat digunakan di dalam blok kode.\"}]', 'Variable Di Php', '2026-06-07 05:12:13'),
(30, 'Quv1ojcbZiS0QjT6IIsujK8rBWf1', 29, 'Sejarah Pki', 'SIA1', 'easy', 'multiple_choice', 5, '[{\"answer\": \"23 Mei 1914\", \"options\": [\"23 Mei 1914\", \"23 Mei 1920\", \"23 Mei 1926\", \"23 Mei 1930\"], \"question\": \"Kapan Partai Komunis Indonesia (PKI) pertama kali didirikan?\", \"explanation\": \"PKI didirikan pada 23 Mei 1914 dengan nama awal Indische Sociaal-Democratische Vereeniging (ISDV), yang kemudian berganti nama menjadi PKI pada tahun 1920.\"}, {\"answer\": \"Semaun\", \"options\": [\"Semaun\", \"Tan Malaka\", \"Musso\", \"D.N. Aidit\"], \"question\": \"Siapa tokoh yang dikenal sebagai pendiri utama PKI?\", \"explanation\": \"Semaun adalah salah satu pendiri ISDV yang kemudian menjadi PKI, dan ia menjadi ketua pertama PKI pada tahun 1920.\"}, {\"answer\": \"Jawa Barat dan Sumatera Barat\", \"options\": [\"Jawa Barat dan Sumatera Barat\", \"Jawa Tengah dan Jawa Timur\", \"Sumatera Utara dan Kalimantan\", \"Sulawesi dan Maluku\"], \"question\": \"Pemberontakan PKI tahun 1926 terjadi di daerah mana?\", \"explanation\": \"Pemberontakan PKI tahun 1926 melanda beberapa daerah, terutama di Jawa Barat (seperti Batavia dan Banten) serta Sumatera Barat.\"}, {\"answer\": \"D.N. Aidit\", \"options\": [\"D.N. Aidit\", \"Musso\", \"Tan Malaka\", \"Semaun\"], \"question\": \"Siapa pemimpin PKI yang paling berpengaruh pada masa pemerintahan Presiden Soekarno?\", \"explanation\": \"D.N. Aidit menjadi ketua PKI dari tahun 1951 hingga 1965 dan membawa PKI menjadi partai komunis terbesar di luar Tiongkok dan Uni Soviet.\"}, {\"answer\": \"Gerakan 30 September (G30S)\", \"options\": [\"Gerakan 30 September (G30S)\", \"Pemberontakan PKI Madiun 1948\", \"Peristiwa Tanjung Morawa\", \"Konfrontasi dengan Malaysia\"], \"question\": \"Peristiwa apa yang menjadi awal dari pembubaran PKI pada tahun 1965?\", \"explanation\": \"Gerakan 30 September 1965 yang didalangi oleh PKI menjadi pemicu utama pembubaran PKI dan berakhirnya pengaruh komunis di Indonesia.\"}]', 'Sejarah Pki', '2026-06-07 05:21:32'),
(31, 'Quv1ojcbZiS0QjT6IIsujK8rBWf1', 29, 'fokus ke framework js ya', 'SIA1', 'easy', 'multiple_choice', 5, '[{\"answer\": \"B. Kerangka kerja untuk memudahkan pengembangan aplikasi web\", \"options\": [\"A. Library untuk styling\", \"B. Kerangka kerja untuk memudahkan pengembangan aplikasi web\", \"C. Bahasa pemrograman\", \"D. Database\"], \"question\": \"Apa yang dimaksud dengan framework JavaScript?\", \"explanation\": \"Framework JavaScript menyediakan struktur dan alat bantu untuk mempercepat dan memudahkan pengembangan aplikasi web.\"}, {\"answer\": \"C. React\", \"options\": [\"A. Laravel\", \"B. Django\", \"C. React\", \"D. Flask\"], \"question\": \"Manakah dari berikut ini yang termasuk framework JavaScript front-end?\", \"explanation\": \"React adalah library/framework JavaScript yang populer untuk membangun antarmuka pengguna di sisi front-end.\"}, {\"answer\": \"A. Membangun UI interaktif\", \"options\": [\"A. Membangun UI interaktif\", \"B. Mengelola database\", \"C. Menulis CSS\", \"D. Mengatur server\"], \"question\": \"Apa fungsi utama dari Vue.js?\", \"explanation\": \"Vue.js adalah framework JavaScript yang digunakan untuk membangun antarmuka pengguna yang interaktif dan reaktif.\"}, {\"answer\": \"C. Angular\", \"options\": [\"A. React\", \"B. Vue\", \"C. Angular\", \"D. jQuery\"], \"question\": \"Framework JavaScript yang dikembangkan oleh Google adalah...\", \"explanation\": \"Angular adalah framework JavaScript yang dikembangkan dan dikelola oleh Google.\"}, {\"answer\": \"A. Mempercepat pengembangan\", \"options\": [\"A. Mempercepat pengembangan\", \"B. Menambah beban server\", \"C. Memperlambat aplikasi\", \"D. Tidak memiliki dokumentasi\"], \"question\": \"Apa keuntungan menggunakan framework JavaScript?\", \"explanation\": \"Framework JavaScript menyediakan komponen siap pakai dan struktur yang jelas, sehingga mempercepat proses pengembangan aplikasi.\"}]', 'fokus ke framework js ya', '2026-06-07 05:22:52'),
(32, 'Quv1ojcbZiS0QjT6IIsujK8rBWf1', 29, 'fokus ke framework js ya', 'SIA1', 'hard', 'multiple_choice', 5, '[{\"answer\": \"Tidak ada re-render, perubahan akan hilang pada render berikutnya\", \"options\": [\"Komponen akan langsung re-render dengan nilai baru\", \"Tidak ada re-render, perubahan akan hilang pada render berikutnya\", \"React akan mengabaikan perubahan dan memicu error\", \"State akan berubah tetapi komponen tidak akan re-render\"], \"question\": \"Dalam React, jika Anda mengubah state secara langsung (misal: this.state.count = 5) tanpa menggunakan setState, apa yang akan terjadi?\", \"explanation\": \"React tidak akan mendeteksi mutasi langsung pada state. Saat setState dipanggil, React akan membandingkan state lama dan baru untuk memicu re-render. Mutasi langsung tidak memicu perbandingan, sehingga perubahan akan ditimpa saat render berikutnya.\"}, {\"answer\": \"Properti baru tidak reaktif, perlu menggunakan Vue.set()\", \"options\": [\"Properti baru secara otomatis menjadi reaktif karena Vue menggunakan Proxy\", \"Properti baru tidak reaktif, perlu menggunakan Vue.set()\", \"Properti baru akan reaktif hanya jika dideklarasikan di data\", \"Properti baru akan memicu error karena tidak bisa ditambahkan\"], \"question\": \"Di Vue.js 2, bagaimana cara kerja reaktivitas pada properti objek yang ditambahkan setelah inisialisasi (misal: this.obj.newProp = \'value\')?\", \"explanation\": \"Vue 2 menggunakan Object.defineProperty untuk melacak perubahan, sehingga hanya properti yang sudah ada saat inisialisasi yang reaktif. Untuk menambahkan properti baru secara reaktif, harus menggunakan Vue.set() atau this.$set().\"}, {\"answer\": \"OnPush hanya mengecek perubahan saat input binding berubah atau event terjadi, Default mengecek setiap perubahan di seluruh komponen\", \"options\": [\"OnPush hanya mengecek perubahan saat event terjadi, Default mengecek setiap perubahan data\", \"Default menonaktifkan deteksi perubahan, OnPush mengaktifkannya\", \"OnPush hanya mengecek perubahan saat input binding berubah atau event terjadi, Default mengecek setiap perubahan di seluruh komponen\", \"Default lebih cepat karena tidak menggunakan zone.js\"], \"question\": \"Di Angular, apa perbedaan utama antara ChangeDetectionStrategy.Default dan ChangeDetectionStrategy.OnPush?\", \"explanation\": \"Dengan Default, Angular menggunakan zone.js untuk mendeteksi perubahan secara otomatis (misal: setTimeout, HTTP). OnPush membatasi deteksi hanya ketika input reference berubah (immutable) atau event dari komponen itu sendiri, sehingga lebih optimal.\"}, {\"answer\": \"Svelte mengkompilasi komponen menjadi kode imperatif yang langsung memanipulasi DOM, React menggunakan diffing virtual DOM di runtime\", \"options\": [\"Svelte menggunakan virtual DOM di runtime, React menggunakan kompilasi\", \"Svelte mengkompilasi komponen menjadi kode imperatif yang langsung memanipulasi DOM, React menggunakan diffing virtual DOM di runtime\", \"Svelte menggunakan Proxy untuk reaktivitas, React menggunakan Object.defineProperty\", \"Svelte dan React sama-sama menggunakan virtual DOM, hanya sintaks yang berbeda\"], \"question\": \"Di Svelte, bagaimana compiler menangani reaktivitas dibandingkan dengan framework berbasis virtual DOM seperti React?\", \"explanation\": \"Svelte adalah compiler yang mengubah komponen menjadi kode JavaScript murni saat build time, sehingga tidak perlu virtual DOM. React menggunakan virtual DOM untuk menghitung perubahan dan memperbarui DOM secara efisien di runtime.\"}, {\"answer\": \"getStaticProps mengambil data saat build time untuk static generation, getServerSideProps mengambil data setiap request untuk server-side rendering\", \"options\": [\"getStaticProps mengambil data saat runtime setiap request, getServerSideProps mengambil data saat build time\", \"getStaticProps mengambil data saat build time untuk static generation, getServerSideProps mengambil data setiap request untuk server-side rendering\", \"getStaticProps hanya untuk halaman statis, getServerSideProps untuk halaman dinamis tanpa caching\", \"getStaticProps dan getServerSideProps sama-sama mengambil data saat build time\"], \"question\": \"Di Next.js (framework React), apa perbedaan antara getStaticProps dan getServerSideProps dalam hal kapan data diambil dan bagaimana halaman dirender?\", \"explanation\": \"getStaticProps digunakan untuk Static Site Generation (SSG) di mana data diambil sekali saat build dan halaman di-cache. getServerSideProps digunakan untuk Server-Side Rendering (SSR) di mana data diambil setiap kali ada request, sehingga halaman selalu fresh.\"}]', 'fokus ke framework js ya', '2026-06-07 05:26:04'),
(33, 'Quv1ojcbZiS0QjT6IIsujK8rBWf1', 29, 'Sejarah Pki', 'SIA1', 'hard', 'multiple_choice', 5, '[{\"answer\": \"Indische Sociaal-Democratische Vereeniging (ISDV)\", \"options\": [\"Indische Sociaal-Democratische Vereeniging (ISDV)\", \"Sarekat Islam (SI)\", \"Budi Utomo\", \"Partai Nasional Indonesia (PNI)\"], \"question\": \"Partai Komunis Indonesia (PKI) resmi didirikan pada tahun 1914. Namun, cikal bakal organisasi ini sebelumnya sudah ada dalam bentuk lain. Organisasi apakah yang menjadi embrio berdirinya PKI?\", \"explanation\": \"PKI berawal dari ISDV yang didirikan oleh tokoh-tokoh sosialis Belanda pada tahun 1914. ISDV kemudian berubah nama menjadi PKI pada tahun 1920.\"}, {\"answer\": \"PKI menganut paham Marxisme-Leninisme dan bertujuan menggulingkan kapitalisme serta imperialisme secara revolusioner\", \"options\": [\"PKI lebih fokus pada perjuangan melalui jalur diplomasi dengan Belanda\", \"PKI menganut paham Marxisme-Leninisme dan bertujuan menggulingkan kapitalisme serta imperialisme secara revolusioner\", \"PKI hanya bergerak di bidang sosial dan budaya tanpa menyentuh politik\", \"PKI merupakan organisasi yang didirikan oleh kalangan bangsawan Jawa\"], \"question\": \"Pada masa Politik Etis (1901), pendidikan bagi pribumi mulai dibuka. Hal ini melahirkan kaum intelektual yang kemudian mendirikan berbagai organisasi pergerakan. PKI sebagai partai komunis pertama di Asia memiliki karakteristik yang berbeda dengan organisasi lain. Manakah pernyataan yang PALING TEPAT mengenai perbedaan PKI dengan organisasi pergerakan lain seperti Budi Utomo atau Sarekat Islam pada awal abad ke-20?\", \"explanation\": \"PKI berbeda karena berideologi komunis yang menginginkan perubahan sistem secara revolusioner, sementara Budi Utomo lebih bersifat kultural dan Sarekat Islam awalnya fokus pada ekonomi dan agama.\"}, {\"answer\": \"Jawa Barat dan Sumatera Barat\", \"options\": [\"Jawa Barat dan Sumatera Barat\", \"Jawa Tengah dan Yogyakarta\", \"Sulawesi Selatan dan Maluku\", \"Bali dan Nusa Tenggara\"], \"question\": \"Salah satu pemberontakan besar yang dipengaruhi oleh PKI terjadi pada tahun 1926-1927. Pemberontakan ini melibatkan partai komunis dan mendapat respons keras dari pemerintah kolonial Belanda. Di manakah pusat pemberontakan PKI pada tahun 1926 tersebut?\", \"explanation\": \"Pemberontakan PKI 1926 terjadi di beberapa daerah, terutama di Banten (Jawa Barat) dan Sumatera Barat. Pemberontakan ini berhasil dipadamkan oleh Belanda dan menyebabkan banyak kader PKI diasingkan.\"}, {\"answer\": \"PKI terlibat dalam pemberontakan terhadap pemerintah RI yang dikenal sebagai Peristiwa Madiun 1948\", \"options\": [\"PKI secara konsisten mendukung pemerintah RI dan ikut bertempur melawan Belanda\", \"PKI menolak perjuangan bersenjata dan memilih bernegosiasi dengan Belanda\", \"PKI terlibat dalam pemberontakan terhadap pemerintah RI yang dikenal sebagai Peristiwa Madiun 1948\", \"PKI memilih netral dan tidak terlibat dalam konflik bersenjata\"], \"question\": \"Setelah Indonesia merdeka, PKI kembali aktif dan terlibat dalam berbagai peristiwa politik. Pada masa Agresi Militer Belanda I (1947) dan Agresi Militer II (1948), bagaimana sikap PKI terhadap perjuangan mempertahankan kemerdekaan?\", \"explanation\": \"Pada September 1948, PKI di bawah Musso memproklamasikan berdirinya pemerintahan Soviet di Madiun, yang merupakan pemberontakan terhadap pemerintah RI. Peristiwa ini terjadi di tengah Agresi Militer Belanda II.\"}, {\"answer\": \"PKI tetap eksis secara legal dan ikut serta dalam pemilu 1955\", \"options\": [\"PKI dibubarkan dan dilarang secara permanen oleh pemerintah RI\", \"PKI tetap eksis secara legal dan ikut serta dalam pemilu 1955\", \"PKI berganti nama menjadi Partai Murba dan terus beraktivitas\", \"PKI melakukan reorganisasi dan bergabung dengan pemerintah RIS\"], \"question\": \"Peristiwa Madiun 1948 merupakan salah satu titik balik dalam sejarah PKI. Setelah pemberontakan tersebut, bagaimana nasib PKI pada masa berikutnya hingga pengakuan kedaulatan RI tahun 1949?\", \"explanation\": \"Meskipun pemberontakan Madiun dipadamkan, PKI tidak dibubarkan. Setelah pengakuan kedaulatan, PKI kembali bangkit dan menjadi salah satu partai besar yang ikut Pemilu 1955, bahkan meraih suara signifikan.\"}]', 'Sejarah Pki', '2026-06-07 05:26:30'),
(34, 'Quv1ojcbZiS0QjT6IIsujK8rBWf1', 29, 'UAS', 'SIA1', 'hard', 'multiple_choice', 5, '[{\"answer\": \"Menggunakan token CSRF yang unik per sesi dan memvalidasinya di server\", \"options\": [\"Menggunakan token CSRF yang unik per sesi dan memvalidasinya di server\", \"Menonaktifkan semua metode POST dan hanya menggunakan GET\", \"Mengenkripsi data form dengan algoritma AES sebelum dikirim\", \"Menambahkan header \'X-Requested-With: XMLHttpRequest\' pada setiap permintaan\"], \"question\": \"Dalam pengembangan aplikasi web menggunakan framework MVC, bagaimana cara paling efektif untuk mencegah serangan Cross-Site Request Forgery (CSRF) pada form yang dikirimkan melalui metode POST?\", \"explanation\": \"CSRF token adalah mekanisme standar untuk memastikan bahwa permintaan POST berasal dari sumber yang sah, bukan dari situs jahat. Token di-generate per sesi dan disisipkan di form, lalu divalidasi di server. Opsi lain tidak efektif karena menonaktifkan POST tidak praktis, enkripsi tidak mencegah CSRF, dan header \'X-Requested-With\' bisa dipalsukan.\"}, {\"answer\": \"Menggunakan eager loading dengan metode \'with()\' untuk memuat relasi dalam satu query\", \"options\": [\"Menggunakan eager loading dengan metode \'with()\' untuk memuat relasi dalam satu query\", \"Menulis query SQL mentah untuk setiap relasi secara manual\", \"Menonaktifkan lazy loading dan menggunakan hanya query builder\", \"Menyimpan semua data dalam cache untuk menghindari query berulang\"], \"question\": \"Dalam pengembangan REST API menggunakan framework PHP modern (seperti Laravel), masalah N+1 query sering terjadi saat mengambil relasi data. Strategi apa yang paling tepat untuk mengatasi masalah ini?\", \"explanation\": \"Eager loading memungkinkan pengambilan data relasi dalam satu query JOIN atau subquery, mengurangi jumlah query dari N+1 menjadi hanya 2 query. Opsi lain tidak efisien: query manual tetap menyebabkan N+1, menonaktifkan lazy loading tidak otomatis mengatasi masalah, dan caching tidak relevan untuk masalah struktural ini.\"}, {\"answer\": \"Membuat middleware yang membaca token JWT, mengekstrak role dari payload, dan membandingkannya dengan role yang diizinkan\", \"options\": [\"Membuat middleware yang membaca token JWT, mengekstrak role dari payload, dan membandingkannya dengan role yang diizinkan\", \"Menyimpan role pengguna di session dan memeriksanya di setiap controller tanpa middleware\", \"Menggunakan filter di file konfigurasi rute untuk memblokir akses berdasarkan IP\", \"Menambahkan pengecekan role di setiap view template untuk menyembunyikan link admin\"], \"question\": \"Dalam sistem autentikasi dan otorisasi berbasis role (RBAC) pada aplikasi web, bagaimana cara menerapkan middleware yang memeriksa apakah pengguna memiliki role \'admin\' sebelum mengakses rute tertentu?\", \"explanation\": \"Middleware adalah lapisan yang tepat untuk memvalidasi otorisasi sebelum request mencapai controller. Dengan JWT, role dapat disimpan di payload token dan diverifikasi di middleware. Opsi lain tidak aman: session bisa diubah, filter IP tidak akurat, dan pengecekan di view hanya menyembunyikan UI, bukan melindungi endpoint.\"}, {\"answer\": \"Menggunakan layanan pihak ketiga seperti Pusher atau Firebase yang menyediakan infrastruktur WebSocket\", \"options\": [\"Menggunakan polling HTTP (Ajax) secara periodik sebagai fallback karena WebSocket tidak dapat berjalan di lingkungan tersebut\", \"Mengalihkan ke protokol HTTP/2 yang memiliki fitur server push untuk menggantikan WebSocket\", \"Menggunakan layanan pihak ketiga seperti Pusher atau Firebase yang menyediakan infrastruktur WebSocket\", \"Mengubah arsitektur menjadi serverless dengan fungsi cloud yang menangani koneksi WebSocket\"], \"question\": \"Dalam pengembangan aplikasi web real-time (seperti chat atau notifikasi), teknologi WebSocket digunakan untuk komunikasi dua arah. Apa tantangan utama yang harus diatasi saat mengimplementasikan WebSocket di lingkungan server bersama (shared hosting) yang tidak mendukung koneksi persisten?\", \"explanation\": \"Shared hosting biasanya tidak mengizinkan koneksi persisten karena keterbatasan resource dan firewall. Layanan pihak ketiga menangani WebSocket di server mereka, sementara aplikasi hanya mengirim event melalui API. Polling HTTP tidak real-time, HTTP/2 server push tidak untuk komunikasi dua arah, dan serverless tidak dirancang untuk koneksi panjang.\"}, {\"answer\": \"Menyimpan hasil query database di memori (misalnya Redis) dengan waktu kedaluwarsa yang sesuai\", \"options\": [\"Mengimplementasikan cache di sisi klien dengan header Cache-Control dan ETag\", \"Menyimpan hasil query database di memori (misalnya Redis) dengan waktu kedaluwarsa yang sesuai\", \"Menggunakan database NoSQL seperti MongoDB sebagai pengganti database relasional\", \"Mengompresi respons API dengan Gzip untuk mengurangi ukuran data yang dikirim\"], \"question\": \"Dalam pengembangan API yang melayani banyak permintaan, strategi caching apa yang paling tepat untuk mengurangi beban database dan meningkatkan respons time untuk data yang jarang berubah?\", \"explanation\": \"Caching di sisi server menggunakan Redis memungkinkan penyimpanan hasil query yang sering diminta, mengurangi akses database. Waktu kedaluwarsa memastikan data tetap segar. Cache sisi klien hanya mengurangi permintaan, bukan beban database. Mengganti database tidak otomatis caching, dan kompresi hanya mengurangi bandwidth, bukan beban query.\"}]', 'UAS', '2026-06-07 05:28:38');
INSERT INTO `questions` (`id`, `user_id`, `subject_id`, `title`, `class`, `difficulty`, `type`, `total_questions`, `questions_data`, `prompt_used`, `created_at`) VALUES
(35, 'Quv1ojcbZiS0QjT6IIsujK8rBWf1', 29, 'Variable Di Php', 'SIA1', 'hard', 'multiple_choice', 5, '[{\"answer\": \"$\", \"options\": [\"$\", \"#\", \"@\", \"&\"], \"question\": \"Dalam PHP, variabel dideklarasikan dengan awalan simbol apa?\", \"explanation\": \"Di PHP, semua variabel harus diawali dengan simbol dollar ($).\"}, {\"answer\": \"$nama_saya\", \"options\": [\"$nama_saya\", \"$123nama\", \"$nama-saya\", \"$nama saya\"], \"question\": \"Manakah dari berikut ini yang merupakan nama variabel PHP yang valid?\", \"explanation\": \"Nama variabel PHP harus diawali dengan huruf atau underscore, dan hanya boleh berisi huruf, angka, dan underscore. $nama_saya memenuhi aturan tersebut.\"}, {\"answer\": \"echo $umur;\", \"options\": [\"echo $umur;\", \"echo \'umur\';\", \"print ($umur);\", \"output $umur;\"], \"question\": \"Bagaimana cara menampilkan nilai variabel $umur ke layar menggunakan echo?\", \"explanation\": \"Perintah echo diikuti dengan nama variabel tanpa tanda petik akan menampilkan nilai variabel tersebut.\"}, {\"answer\": \"float\", \"options\": [\"integer\", \"float\", \"string\", \"boolean\"], \"question\": \"Tipe data apa yang akan disimpan oleh variabel $x = 10.5; ?\", \"explanation\": \"Karena nilai 10.5 memiliki desimal, maka PHP akan menyimpannya sebagai tipe data float (atau double).\"}, {\"answer\": \"Menggabungkan string\", \"options\": [\"Menggabungkan string\", \"Membandingkan nilai\", \"Menambahkan angka\", \"Mengalikan angka\"], \"question\": \"Apa fungsi operator titik (.) dalam konteks variabel PHP?\", \"explanation\": \"Operator titik (.) di PHP digunakan untuk concatenation atau penggabungan string.\"}]', 'Variable Di Php', '2026-06-07 05:28:58'),
(36, 'Quv1ojcbZiS0QjT6IIsujK8rBWf1', 29, 'UAS', 'SIA1', 'hard', 'multiple_choice', 5, '[{\"answer\": \"Menggunakan token CSRF yang unik per sesi dan memvalidasinya di server\", \"options\": [\"Menggunakan token CSRF yang unik per sesi dan memvalidasinya di server\", \"Menonaktifkan semua metode POST dan hanya menggunakan GET\", \"Mengenkripsi data form dengan algoritma AES sebelum dikirim\", \"Menambahkan header \'X-Requested-With: XMLHttpRequest\' pada setiap permintaan\"], \"question\": \"Dalam pengembangan aplikasi web menggunakan framework MVC, bagaimana cara paling efektif untuk mencegah serangan Cross-Site Request Forgery (CSRF) pada form yang dikirimkan melalui metode POST?\", \"explanation\": \"CSRF token adalah mekanisme standar untuk memastikan bahwa permintaan POST berasal dari sumber yang sah, bukan dari situs jahat. Token di-generate per sesi dan disisipkan di form, lalu divalidasi di server. Opsi lain tidak efektif karena menonaktifkan POST tidak praktis, enkripsi tidak mencegah CSRF, dan header \'X-Requested-With\' bisa dipalsukan.\"}, {\"answer\": \"Menggunakan eager loading dengan metode \'with()\' untuk memuat relasi dalam satu query\", \"options\": [\"Menggunakan eager loading dengan metode \'with()\' untuk memuat relasi dalam satu query\", \"Menulis query SQL mentah untuk setiap relasi secara manual\", \"Menonaktifkan lazy loading dan menggunakan hanya query builder\", \"Menyimpan semua data dalam cache untuk menghindari query berulang\"], \"question\": \"Dalam pengembangan REST API menggunakan framework PHP modern (seperti Laravel), masalah N+1 query sering terjadi saat mengambil relasi data. Strategi apa yang paling tepat untuk mengatasi masalah ini?\", \"explanation\": \"Eager loading memungkinkan pengambilan data relasi dalam satu query JOIN atau subquery, mengurangi jumlah query dari N+1 menjadi hanya 2 query. Opsi lain tidak efisien: query manual tetap menyebabkan N+1, menonaktifkan lazy loading tidak otomatis mengatasi masalah, dan caching tidak relevan untuk masalah struktural ini.\"}, {\"answer\": \"Membuat middleware yang membaca token JWT, mengekstrak role dari payload, dan membandingkannya dengan role yang diizinkan\", \"options\": [\"Membuat middleware yang membaca token JWT, mengekstrak role dari payload, dan membandingkannya dengan role yang diizinkan\", \"Menyimpan role pengguna di session dan memeriksanya di setiap controller tanpa middleware\", \"Menggunakan filter di file konfigurasi rute untuk memblokir akses berdasarkan IP\", \"Menambahkan pengecekan role di setiap view template untuk menyembunyikan link admin\"], \"question\": \"Dalam sistem autentikasi dan otorisasi berbasis role (RBAC) pada aplikasi web, bagaimana cara menerapkan middleware yang memeriksa apakah pengguna memiliki role \'admin\' sebelum mengakses rute tertentu?\", \"explanation\": \"Middleware adalah lapisan yang tepat untuk memvalidasi otorisasi sebelum request mencapai controller. Dengan JWT, role dapat disimpan di payload token dan diverifikasi di middleware. Opsi lain tidak aman: session bisa diubah, filter IP tidak akurat, dan pengecekan di view hanya menyembunyikan UI, bukan melindungi endpoint.\"}, {\"answer\": \"Menggunakan layanan pihak ketiga seperti Pusher atau Firebase yang menyediakan infrastruktur WebSocket\", \"options\": [\"Menggunakan polling HTTP (Ajax) secara periodik sebagai fallback karena WebSocket tidak dapat berjalan di lingkungan tersebut\", \"Mengalihkan ke protokol HTTP/2 yang memiliki fitur server push untuk menggantikan WebSocket\", \"Menggunakan layanan pihak ketiga seperti Pusher atau Firebase yang menyediakan infrastruktur WebSocket\", \"Mengubah arsitektur menjadi serverless dengan fungsi cloud yang menangani koneksi WebSocket\"], \"question\": \"Dalam pengembangan aplikasi web real-time (seperti chat atau notifikasi), teknologi WebSocket digunakan untuk komunikasi dua arah. Apa tantangan utama yang harus diatasi saat mengimplementasikan WebSocket di lingkungan server bersama (shared hosting) yang tidak mendukung koneksi persisten?\", \"explanation\": \"Shared hosting biasanya tidak mengizinkan koneksi persisten karena keterbatasan resource dan firewall. Layanan pihak ketiga menangani WebSocket di server mereka, sementara aplikasi hanya mengirim event melalui API. Polling HTTP tidak real-time, HTTP/2 server push tidak untuk komunikasi dua arah, dan serverless tidak dirancang untuk koneksi panjang.\"}, {\"answer\": \"Menyimpan hasil query database di memori (misalnya Redis) dengan waktu kedaluwarsa yang sesuai\", \"options\": [\"Mengimplementasikan cache di sisi klien dengan header Cache-Control dan ETag\", \"Menyimpan hasil query database di memori (misalnya Redis) dengan waktu kedaluwarsa yang sesuai\", \"Menggunakan database NoSQL seperti MongoDB sebagai pengganti database relasional\", \"Mengompresi respons API dengan Gzip untuk mengurangi ukuran data yang dikirim\"], \"question\": \"Dalam pengembangan API yang melayani banyak permintaan, strategi caching apa yang paling tepat untuk mengurangi beban database dan meningkatkan respons time untuk data yang jarang berubah?\", \"explanation\": \"Caching di sisi server menggunakan Redis memungkinkan penyimpanan hasil query yang sering diminta, mengurangi akses database. Waktu kedaluwarsa memastikan data tetap segar. Cache sisi klien hanya mengurangi permintaan, bukan beban database. Mengganti database tidak otomatis caching, dan kompresi hanya mengurangi bandwidth, bukan beban query.\"}]', 'UAS', '2026-06-07 05:29:28'),
(37, 'Quv1ojcbZiS0QjT6IIsujK8rBWf1', 29, 'UAS', 'SIA1', 'hard', 'multiple_choice', 5, '[{\"answer\": \"Menggunakan token CSRF yang unik per sesi dan memvalidasinya di server\", \"options\": [\"Menggunakan token CSRF yang unik per sesi dan memvalidasinya di server\", \"Menonaktifkan semua metode POST dan hanya menggunakan GET\", \"Mengenkripsi data form dengan algoritma AES sebelum dikirim\", \"Menambahkan header \'X-Requested-With: XMLHttpRequest\' pada setiap permintaan\"], \"question\": \"Dalam pengembangan aplikasi web menggunakan framework MVC, bagaimana cara paling efektif untuk mencegah serangan Cross-Site Request Forgery (CSRF) pada form yang dikirimkan melalui metode POST?\", \"explanation\": \"CSRF token adalah mekanisme standar untuk memastikan bahwa permintaan POST berasal dari sumber yang sah, bukan dari situs jahat. Token di-generate per sesi dan disisipkan di form, lalu divalidasi di server. Opsi lain tidak efektif karena menonaktifkan POST tidak praktis, enkripsi tidak mencegah CSRF, dan header \'X-Requested-With\' bisa dipalsukan.\"}, {\"answer\": \"Menggunakan eager loading dengan metode \'with()\' untuk memuat relasi dalam satu query\", \"options\": [\"Menggunakan eager loading dengan metode \'with()\' untuk memuat relasi dalam satu query\", \"Menulis query SQL mentah untuk setiap relasi secara manual\", \"Menonaktifkan lazy loading dan menggunakan hanya query builder\", \"Menyimpan semua data dalam cache untuk menghindari query berulang\"], \"question\": \"Dalam pengembangan REST API menggunakan framework PHP modern (seperti Laravel), masalah N+1 query sering terjadi saat mengambil relasi data. Strategi apa yang paling tepat untuk mengatasi masalah ini?\", \"explanation\": \"Eager loading memungkinkan pengambilan data relasi dalam satu query JOIN atau subquery, mengurangi jumlah query dari N+1 menjadi hanya 2 query. Opsi lain tidak efisien: query manual tetap menyebabkan N+1, menonaktifkan lazy loading tidak otomatis mengatasi masalah, dan caching tidak relevan untuk masalah struktural ini.\"}, {\"answer\": \"Membuat middleware yang membaca token JWT, mengekstrak role dari payload, dan membandingkannya dengan role yang diizinkan\", \"options\": [\"Membuat middleware yang membaca token JWT, mengekstrak role dari payload, dan membandingkannya dengan role yang diizinkan\", \"Menyimpan role pengguna di session dan memeriksanya di setiap controller tanpa middleware\", \"Menggunakan filter di file konfigurasi rute untuk memblokir akses berdasarkan IP\", \"Menambahkan pengecekan role di setiap view template untuk menyembunyikan link admin\"], \"question\": \"Dalam sistem autentikasi dan otorisasi berbasis role (RBAC) pada aplikasi web, bagaimana cara menerapkan middleware yang memeriksa apakah pengguna memiliki role \'admin\' sebelum mengakses rute tertentu?\", \"explanation\": \"Middleware adalah lapisan yang tepat untuk memvalidasi otorisasi sebelum request mencapai controller. Dengan JWT, role dapat disimpan di payload token dan diverifikasi di middleware. Opsi lain tidak aman: session bisa diubah, filter IP tidak akurat, dan pengecekan di view hanya menyembunyikan UI, bukan melindungi endpoint.\"}, {\"answer\": \"Menggunakan layanan pihak ketiga seperti Pusher atau Firebase yang menyediakan infrastruktur WebSocket\", \"options\": [\"Menggunakan polling HTTP (Ajax) secara periodik sebagai fallback karena WebSocket tidak dapat berjalan di lingkungan tersebut\", \"Mengalihkan ke protokol HTTP/2 yang memiliki fitur server push untuk menggantikan WebSocket\", \"Menggunakan layanan pihak ketiga seperti Pusher atau Firebase yang menyediakan infrastruktur WebSocket\", \"Mengubah arsitektur menjadi serverless dengan fungsi cloud yang menangani koneksi WebSocket\"], \"question\": \"Dalam pengembangan aplikasi web real-time (seperti chat atau notifikasi), teknologi WebSocket digunakan untuk komunikasi dua arah. Apa tantangan utama yang harus diatasi saat mengimplementasikan WebSocket di lingkungan server bersama (shared hosting) yang tidak mendukung koneksi persisten?\", \"explanation\": \"Shared hosting biasanya tidak mengizinkan koneksi persisten karena keterbatasan resource dan firewall. Layanan pihak ketiga menangani WebSocket di server mereka, sementara aplikasi hanya mengirim event melalui API. Polling HTTP tidak real-time, HTTP/2 server push tidak untuk komunikasi dua arah, dan serverless tidak dirancang untuk koneksi panjang.\"}, {\"answer\": \"Menyimpan hasil query database di memori (misalnya Redis) dengan waktu kedaluwarsa yang sesuai\", \"options\": [\"Mengimplementasikan cache di sisi klien dengan header Cache-Control dan ETag\", \"Menyimpan hasil query database di memori (misalnya Redis) dengan waktu kedaluwarsa yang sesuai\", \"Menggunakan database NoSQL seperti MongoDB sebagai pengganti database relasional\", \"Mengompresi respons API dengan Gzip untuk mengurangi ukuran data yang dikirim\"], \"question\": \"Dalam pengembangan API yang melayani banyak permintaan, strategi caching apa yang paling tepat untuk mengurangi beban database dan meningkatkan respons time untuk data yang jarang berubah?\", \"explanation\": \"Caching di sisi server menggunakan Redis memungkinkan penyimpanan hasil query yang sering diminta, mengurangi akses database. Waktu kedaluwarsa memastikan data tetap segar. Cache sisi klien hanya mengurangi permintaan, bukan beban database. Mengganti database tidak otomatis caching, dan kompresi hanya mengurangi bandwidth, bukan beban query.\"}]', 'UAS', '2026-06-07 05:30:37'),
(38, 'Quv1ojcbZiS0QjT6IIsujK8rBWf1', 29, 'Variable Di Php', 'SIA1', 'hard', 'multiple_choice', 5, '[{\"answer\": \"10\", \"options\": [\"5\", \"10\", \"Error\", \"Null\"], \"question\": \"Dalam PHP, apa yang akan dihasilkan oleh kode berikut? <?php $a = 5; $b = &$a; $b = 10; echo $a; ?>\", \"explanation\": \"Dengan menggunakan operator referensi (&), $b menjadi referensi ke $a. Perubahan pada $b juga mengubah $a, sehingga $a bernilai 10.\"}, {\"answer\": \"bool(true) bool(false)\", \"options\": [\"bool(true) bool(true)\", \"bool(true) bool(false)\", \"bool(false) bool(false)\", \"bool(false) bool(true)\"], \"question\": \"Perhatikan kode PHP: <?php $x = \'5\'; $y = 5; var_dump($x == $y); var_dump($x === $y); ?> Output yang benar adalah?\", \"explanation\": \"Operator == melakukan perbandingan longgar, sehingga string \'5\' dianggap sama dengan integer 5. Operator === melakukan perbandingan ketat, sehingga tipe data berbeda menghasilkan false.\"}, {\"answer\": \"20\", \"options\": [\"10\", \"20\", \"Error\", \"Null\"], \"question\": \"Dalam PHP, apa output dari kode berikut? <?php function test() { global $a; $a = 20; } $a = 10; test(); echo $a; ?>\", \"explanation\": \"Dengan menggunakan keyword \'global\' di dalam fungsi, variabel $a merujuk ke variabel global $a yang dideklarasikan di luar fungsi. Perubahan di dalam fungsi akan mempengaruhi nilai global.\"}, {\"answer\": \"test\", \"options\": [\"value\", \"test\", \"Error\", \"Null\"], \"question\": \"Apa hasil dari kode PHP ini? <?php $var = \'value\'; $$var = \'test\'; echo $value; ?>\", \"explanation\": \"Ini adalah contoh variable variables. $$var berarti variabel dengan nama yang sama dengan nilai $var, yaitu $value. Jadi $value = \'test\', dan echo $value menghasilkan \'test\'.\"}, {\"answer\": \"Array ( [0] => 2 [1] => 4 [2] => 6 )\", \"options\": [\"Array ( [0] => 2 [1] => 4 [2] => 6 )\", \"Array ( [0] => 1 [1] => 2 [2] => 3 )\", \"Array ( [0] => 2 [1] => 4 [2] => 3 )\", \"Error\"], \"question\": \"Perhatikan kode PHP: <?php $a = [1, 2, 3]; foreach ($a as &$v) { $v = $v * 2; } unset($v); print_r($a); ?> Apa outputnya?\", \"explanation\": \"Dengan menggunakan referensi (&$v) dalam foreach, setiap elemen array dimodifikasi secara langsung. Setelah loop, unset($v) penting untuk menghapus referensi. Hasilnya setiap elemen dikalikan 2.\"}]', 'Variable Di Php', '2026-06-07 05:31:05'),
(39, 'Quv1ojcbZiS0QjT6IIsujK8rBWf1', 29, 'fokus ke framework js ya', 'SIA1', 'hard', 'essay', 5, '[{\"answer\": \"React menggunakan Virtual DOM dengan pendekatan \'render → diff → patch\'. Setiap perubahan state memicu re-render seluruh komponen, lalu React membandingkan Virtual DOM baru dengan sebelumnya (reconciliation) menggunakan algoritma diffing (key, type, props) dan melakukan patch ke DOM nyata secara batch. Untuk perubahan state kompleks, React mengandalkan immutability (setState dengan objek baru) agar diffing efektif. Vue 3 menggunakan sistem reaktivitas berbasis Proxy (reactive/ref) yang melacak ketergantungan secara granular. Saat data berubah, hanya komponen yang bergantung pada data tersebut yang di-render ulang (fine-grained reactivity). Vue tidak perlu membandingkan seluruh Virtual DOM; ia langsung menandai efek yang perlu diperbarui. Pada update massal, React bisa lebih boros karena re-render seluruh subtree, tetapi dengan React.memo, useMemo, dan useCallback, kita bisa membatasi. Vue lebih efisien untuk update granular, tetapi overhead Proxy bisa terasa pada objek sangat besar. Kesimpulan: React unggul pada aplikasi dengan struktur komponen sederhana, Vue unggul pada aplikasi dengan banyak state reaktif yang saling terkait.\", \"question\": \"Jelaskan perbedaan mendasar antara Virtual DOM di React dan sistem reaktivitas di Vue 3 (Composition API) dalam mekanisme update rendering. Bagaimana masing-masing framework menangani perubahan state yang kompleks dan bersarang? Sertakan analisis performa pada skenario update massal.\", \"explanation\": \"Perbandingan mekanisme update rendering React (Virtual DOM diff) vs Vue 3 (reaktivitas Proxy) beserta penanganan state kompleks dan implikasi performa.\"}, {\"answer\": \"Angular menggunakan Zone.js untuk memicu change detection (CD) secara otomatis setelah event asinkron (click, timer, HTTP, dsb). Strategi Default: Setiap perubahan pada properti komponen (melalui binding) akan memeriksa seluruh pohon komponen dari root ke daun (top-down) setiap kali ada event. Ini bisa menyebabkan penurunan performa pada aplikasi besar. Strategi OnPush: CD hanya berjalan jika input komponen berubah (referensi baru, bukan mutasi), atau jika event berasal dari komponen itu sendiri, atau jika secara eksplisit memanggil ChangeDetectorRef.markForCheck(). OnPush cocok untuk komponen presentasional/dumb yang hanya menerima input immutabel, atau komponen yang tidak sering berubah. Namun, OnPush dapat menyebabkan bug jika developer secara tidak sengaja memutasi objek input (misalnya mengubah properti array tanpa mengganti referensi) sehingga CD tidak terpicu dan tampilan tidak diperbarui. Contoh: sebuah komponen daftar menerima array via @Input, lalu di dalamnya ada tombol yang menambahkan item dengan push() langsung ke array tersebut. Dengan OnPush, perubahan tidak terdeteksi karena referensi array tetap sama. Solusi: buat array baru (spread operator) atau panggil markForCheck().\", \"question\": \"Dalam Angular, jelaskan secara detail cara kerja Change Detection dan bedakan strategi Default dengan OnPush. Kapan sebaiknya seorang developer memilih OnPush? Berikan contoh kasus di mana penggunaan OnPush dapat menyebabkan bug yang sulit dilacak.\", \"explanation\": \"Penjelasan change detection Angular, perbandingan Default vs OnPush, dan contoh bug akibat OnPush.\"}, {\"answer\": \"Redux menggunakan arsitektur unidirectional dengan store global immutable, reducer murni, dan dispatch action. Debugging mudah dengan Redux DevTools yang memungkinkan time-travel. Side effects ditangani dengan middleware seperti Redux Thunk atau Redux Saga, yang menambah kompleksitas. Skalabilitas: baik untuk aplikasi besar karena pola yang ketat, tetapi boilerplate tinggi. TypeScript support baik dengan definisi tipe action, state, dan reducer. Pinia adalah state management resmi Vue 3 yang memanfaatkan Composition API. Setiap store adalah objek reaktif yang bisa diakses langsung, tanpa action/reducer terpisah. Debugging via Vue DevTools (tidak setara time-travel Redux). Side effects langsung ditulis dalam actions sebagai fungsi async biasa, lebih sederhana. Skalabilitas: cukup baik karena modular, tetapi kurang disiplin dibanding Redux sehingga bisa kacau jika tidak terstruktur. TypeScript support sangat baik karena berbasis class atau setup function dengan inferensi tipe otomatis. Developer experience: Pinia lebih ringan dan intuitif, cocok untuk tim kecil hingga menengah. Redux lebih cocok untuk tim besar yang membutuhkan aturan ketat dan traceability tinggi.\", \"question\": \"Bandingkan pendekatan state management antara Redux (React) dengan Pinia (Vue 3) dari segi arsitektur, kemudahan debugging, dan skalabilitas untuk aplikasi enterprise. Bagaimana cara masing-masing menangani side effects? Sertakan analisis tentang TypeScript support dan developer experience.\", \"explanation\": \"Perbandingan Redux vs Pinia dari arsitektur, debugging, side effects, TypeScript, dan skalabilitas.\"}, {\"answer\": \"React.memo mencegah re-render komponen jika props tidak berubah (shallow comparison). useMemo memoisasi nilai hasil komputasi berat agar tidak dihitung ulang setiap render. useCallback memoisasi fungsi agar referensinya stabil, berguna jika fungsi tersebut menjadi dependency useEffect atau dikirim ke komponen anak yang di-memo. Namun, useCallback kontraproduktif jika digunakan tanpa pemahaman dependency. Contoh: sebuah fungsi yang menggunakan state dan props, tetapi dependency array tidak lengkap sehingga fungsi tersebut menangkap nilai lama (stale closure). Akibatnya, komponen anak mungkin tidak mendapatkan fungsi terbaru, menyebabkan bug. Selain itu, useCallback sendiri memiliki overhead memori dan komputasi untuk membandingkan dependency. Jika fungsi sederhana dan komponen anak tidak di-memo, useCallback tidak memberikan manfaat dan malah memperlambat. Kapan tidak perlu optimasi: saat komponen ringan, jumlah render sedikit, atau fungsi hanya dipanggil di komponen yang sama. Prinsip: optimasi hanya jika terbukti ada masalah performa (profil dulu). Dependency array harus selalu mencakup semua variabel yang digunakan di dalam fungsi untuk menghindari stale closure.\", \"question\": \"Bagaimana cara mengoptimalkan performa aplikasi React menggunakan React.memo, useMemo, dan useCallback? Berikan contoh kasus di mana penggunaan useCallback justru kontraproduktif dan jelaskan alasannya. Sertakan penjelasan tentang dependency array dan kapan sebaiknya tidak menggunakan optimasi tersebut.\", \"explanation\": \"Penjelasan React.memo, useMemo, useCallback beserta contoh kontraproduktif dan panduan kapan menggunakannya.\"}, {\"answer\": \"SSR memungkinkan rendering halaman di server menjadi HTML statis, lalu dikirim ke client bersama JavaScript untuk interaktivitas (hydration). Next.js menggunakan getServerSideProps atau getInitialProps untuk fetch data di server. Nuxt.js menggunakan asyncData atau fetch. Tantangan utama: (1) Hydration mismatch: perbedaan antara HTML server dan hasil render client karena data asinkron, waktu, atau API browser (window, localStorage). Solusi: pastikan data identik, hindari kode yang bergantung browser saat SSR (gunakan useEffect/dynamic import dengan ssr:false), dan gunakan suppressHydrationWarning untuk kasus tertentu. (2) Global state: state management seperti Redux atau Pinia perlu diinisialisasi di server dan disinkronkan ke client. Solusi: gunakan store yang di-rehydrate dari data server (misal, serialisasi state ke window.__INITIAL_STATE__). (3) Autentikasi: server tidak memiliki akses ke cookie/session client secara langsung. Solusi: gunakan cookie parsing di server (next-cookie, nuxt-auth), atau token di header Authorization. Pastikan data autentikasi tidak bocor ke HTML. Tantangan lain: performa server (beban rendering), caching, dan konfigurasi routing. Kesimpulan: SSR meningkatkan SEO dan First Contentful Paint, tetapi memerlukan penanganan hati-hati terhadap perbedaan lingkungan server-client.\", \"question\": \"Jelaskan konsep Server-Side Rendering (SSR) pada framework JS modern seperti Next.js (React) atau Nuxt.js (Vue). Apa saja tantangan utama dalam implementasi SSR, terutama terkait hydration mismatch, global state, dan autentikasi? Bagaimana cara mengatasi tantangan tersebut?\", \"explanation\": \"Penjelasan SSR di Next.js/Nuxt.js, tantangan hydration mismatch, global state, autentikasi, dan solusinya.\"}]', 'fokus ke framework js ya', '2026-06-07 05:32:53'),
(40, 'Quv1ojcbZiS0QjT6IIsujK8rBWf1', 29, 'Sejarah Matematika', 'SIA1', 'hard', 'essay', 5, '[{\"answer\": \"Hippasus\", \"options\": [\"Euclid\", \"Pythagoras\", \"Hippasus\", \"Archimedes\"], \"question\": \"Siapakah matematikawan Yunani kuno yang pertama kali membuktikan bahwa akar kuadrat dari 2 adalah bilangan irasional?\", \"explanation\": \"Hippasus dari Metapontum, seorang murid Pythagoras, dikreditkan dengan penemuan bilangan irasional melalui pembuktian bahwa √2 tidak dapat dinyatakan sebagai rasio dua bilangan bulat. Legenda mengatakan ia dibunuh karena penemuan ini bertentangan dengan doktrin Pythagoras.\"}, {\"answer\": \"Isaac Newton dan Gottfried Wilhelm Leibniz\", \"options\": [\"Isaac Newton dan Gottfried Wilhelm Leibniz\", \"Augustin-Louis Cauchy dan Bernhard Riemann\", \"Leonhard Euler dan Joseph-Louis Lagrange\", \"Pierre de Fermat dan Blaise Pascal\"], \"question\": \"Teorema Fundamental Kalkulus yang menghubungkan turunan dan integral pertama kali dirumuskan secara formal oleh siapa?\", \"explanation\": \"Meskipun konsep kalkulus telah muncul sebelumnya, Newton dan Leibniz secara independen mengembangkan notasi dan teorema fundamental yang menghubungkan diferensiasi dan integrasi pada abad ke-17. Cauchy dan Riemann kemudian memberikan formalisasi yang lebih ketat.\"}, {\"answer\": \"Kurt Gödel dan Paul Cohen\", \"options\": [\"Kurt Gödel dan Paul Cohen\", \"Georg Cantor dan David Hilbert\", \"Alonzo Church dan Alan Turing\", \"John von Neumann dan Norbert Wiener\"], \"question\": \"Masalah Hilbert yang pertama, yaitu tentang hipotesis kontinuum, akhirnya terbukti tidak dapat diputuskan dalam teori himpunan Zermelo-Fraenkel. Siapa yang membuktikan hal ini?\", \"explanation\": \"Gödel pada tahun 1940 menunjukkan bahwa hipotesis kontinuum konsisten dengan aksioma ZFC, dan Cohen pada tahun 1963 menunjukkan bahwa negasinya juga konsisten, sehingga membuktikan independensinya dari ZFC.\"}, {\"answer\": \"Carl Friedrich Gauss\", \"options\": [\"Carl Friedrich Gauss\", \"Évariste Galois\", \"Niels Henrik Abel\", \"Augustin-Louis Cauchy\"], \"question\": \"Konsep grup abstrak pertama kali diperkenalkan secara formal oleh siapa dalam karyanya \'Disquisitiones Arithmeticae\'?\", \"explanation\": \"Gauss dalam Disquisitiones Arithmeticae (1801) memperkenalkan konsep grup dalam konteks aritmetika modular, meskipun istilah \'grup\' baru digunakan kemudian oleh Galois dan Cauchy untuk teori persamaan.\"}, {\"answer\": \"Leonhard Euler\", \"options\": [\"Leonhard Euler\", \"Gerolamo Cardano\", \"Rafael Bombelli\", \"Carl Friedrich Gauss\"], \"question\": \"Siapa matematikawan yang pertama kali mengembangkan sistem bilangan kompleks dan memperkenalkan notasi i untuk √-1?\", \"explanation\": \"Euler pada abad ke-18 memperkenalkan notasi i untuk √-1 dalam bukunya \'Introductio in analysin infinitorum\' (1748) dan mengembangkan teori bilangan kompleks secara sistematis, meskipun akar dari bilangan negatif sudah digunakan sebelumnya oleh Cardano dan Bombelli.\"}]', 'Sejarah Matematika', '2026-06-07 05:34:11'),
(41, 'Quv1ojcbZiS0QjT6IIsujK8rBWf1', 29, 'Pengetahuan Umum Tentang Kartun Spongebob', 'SIA1', 'hard', 'multiple_choice', 5, '[{\"answer\": \"Tom Kenny\", \"options\": [\"Tom Kenny\", \"Bill Fagerbakke\", \"Rodger Bumpass\", \"Clancy Brown\"], \"question\": \"Siapa nama aktor yang mengisi suara SpongeBob SquarePants dalam versi asli (Inggris)?\", \"explanation\": \"Tom Kenny adalah pengisi suara asli SpongeBob SquarePants sejak episode pertama.\"}, {\"answer\": \"Sebuah tali\", \"options\": [\"Sebuah tali\", \"Foto Patrick\", \"Sebuah kepiting\", \"Kertas catatan\"], \"question\": \"Pada episode \'The Secret Box\', apa yang sebenarnya ada di dalam kotak rahasia milik SpongeBob?\", \"explanation\": \"Setelah berbagai spekulasi, terungkap bahwa isi kotak rahasia SpongeBob hanyalah sebuah tali biasa.\"}, {\"answer\": \"Plankton\", \"options\": [\"Plankton\", \"Mr. Krabs\", \"Squidward\", \"SpongeBob\"], \"question\": \"Siapa nama pemilik restoran Chum Bucket?\", \"explanation\": \"Plankton adalah pemilik Chum Bucket yang selalu berusaha mencuri resep Krabby Patty.\"}, {\"answer\": \"Bikini Bottom\", \"options\": [\"Bikini Bottom\", \"Krusty Krab\", \"Jellyfish Fields\", \"Goo Lagoon\"], \"question\": \"Di kota manakah SpongeBob dan teman-temannya tinggal?\", \"explanation\": \"Bikini Bottom adalah kota bawah laut yang menjadi setting utama serial SpongeBob SquarePants.\"}, {\"answer\": \"36\", \"options\": [\"36\", \"24\", \"48\", \"12\"], \"question\": \"Berapa jumlah lubang yang terdapat pada tubuh SpongeBob?\", \"explanation\": \"Menurut keterangan resmi, SpongeBob memiliki 36 lubang di tubuhnya yang merupakan ciri khas spons laut.\"}]', 'Pengetahuan Umum Tentang Kartun Spongebob', '2026-06-08 01:42:21'),
(42, 'Quv1ojcbZiS0QjT6IIsujK8rBWf1', 29, 'Ujian Akhir Semester', 'SIA1', 'easy', 'multiple_choice', 5, '[{\"answer\": \"application/controllers\", \"options\": [\"application/controllers\", \"application/views\", \"application/models\", \"system/core\"], \"question\": \"Di dalam framework CodeIgniter 3, folder manakah yang digunakan untuk menyimpan file controller?\", \"explanation\": \"Controller disimpan di folder application/controllers sesuai dengan struktur direktori CodeIgniter 3.\"}, {\"answer\": \"$this->load->view()\", \"options\": [\"$this->load->view()\", \"$this->view->load()\", \"load_view()\", \"$this->render->view()\"], \"question\": \"Fungsi apa yang digunakan di dalam controller CodeIgniter 3 untuk memuat dan menampilkan sebuah view?\", \"explanation\": \"Untuk memuat view di controller, gunakan method $this->load->view(\'nama_view\').\"}, {\"answer\": \"$this->load->model(\'Nama_model\')\", \"options\": [\"$this->load->model(\'Nama_model\')\", \"$this->model->load(\'Nama_model\')\", \"load_model(\'Nama_model\')\", \"$this->load->library(\'Nama_model\')\"], \"question\": \"Bagaimana cara memuat model di dalam controller CodeIgniter 3?\", \"explanation\": \"Model dimuat menggunakan $this->load->model(\'Nama_model\') di dalam controller.\"}, {\"answer\": \"url helper\", \"options\": [\"url helper\", \"html helper\", \"form helper\", \"file helper\"], \"question\": \"Helper apakah yang menyediakan fungsi base_url() dan site_url() di CodeIgniter 3?\", \"explanation\": \"Helper \'url\' menyediakan fungsi seperti base_url() dan site_url() untuk menangani URL.\"}, {\"answer\": \"application/config/database.php\", \"options\": [\"application/config/database.php\", \"application/config/config.php\", \"application/config/db.php\", \"system/config/database.php\"], \"question\": \"Di file manakah konfigurasi database untuk CodeIgniter 3 biasanya diatur?\", \"explanation\": \"Konfigurasi database disimpan di file application/config/database.php dengan array $db.\"}]', 'Ujian Akhir Semester', '2026-06-08 10:37:44'),
(43, 'Quv1ojcbZiS0QjT6IIsujK8rBWf1', 29, 'Sejarah Pki', 'SIA1', 'easy', 'multiple_choice', 5, '[{\"answer\": \"1914\", \"options\": [\"1908\", \"1912\", \"1914\", \"1927\"], \"question\": \"Kapan Partai Komunis Indonesia (PKI) didirikan?\", \"explanation\": \"Berdasarkan materi, PKI didirikan pada tahun 1914 sebagai organisasi pergerakan nasional yang radikal.\"}, {\"answer\": \"Partai Komunis Indonesia\", \"options\": [\"Budi Utomo\", \"Sarekat Islam\", \"Indische Partij\", \"Partai Komunis Indonesia\"], \"question\": \"Organisasi pergerakan nasional yang didirikan pada tahun 1914 adalah...\", \"explanation\": \"Materi menyebutkan bahwa Partai Komunis Indonesia (PKI) berdiri pada tahun 1914.\"}, {\"answer\": \"politik\", \"options\": [\"koperasi\", \"sosial\", \"politik\", \"agama\"], \"question\": \"PKI termasuk dalam kategori organisasi...\", \"explanation\": \"Materi menyebut PKI sebagai bagian dari pergerakan radikal, sehingga termasuk organisasi politik.\"}, {\"answer\": \"20\", \"options\": [\"18\", \"19\", \"20\", \"21\"], \"question\": \"PKI didirikan pada abad ke-...\", \"explanation\": \"Tahun 1914 berada pada abad ke-20.\"}, {\"answer\": \"Politik Etis\", \"options\": [\"Sistem Tanam Paksa\", \"Politik Etis\", \"Kerja Paksa Daendels\", \"Monopoli VOC\"], \"question\": \"PKI muncul setelah penerapan kebijakan...\", \"explanation\": \"Materi menyatakan bahwa Politik Etis membuka akses pendidikan dan melahirkan organisasi pergerakan, termasuk PKI.\"}]', 'Sejarah Pki', '2026-06-08 10:44:42'),
(44, 'Quv1ojcbZiS0QjT6IIsujK8rBWf1', 29, 'UAS', 'SIA1', 'medium', 'multiple_choice', 5, '[{\"answer\": \"<a>\", \"options\": [\"<link>\", \"<a>\", \"<href>\", \"<url>\"], \"question\": \"Manakah dari berikut ini yang merupakan tag HTML untuk membuat hyperlink?\", \"explanation\": \"Tag <a> (anchor) digunakan untuk membuat hyperlink ke halaman lain atau bagian tertentu.\"}, {\"answer\": \"background-color\", \"options\": [\"color\", \"background-color\", \"font-color\", \"bgcolor\"], \"question\": \"Properti CSS apa yang digunakan untuk mengubah warna latar belakang elemen?\", \"explanation\": \"Properti background-color mengatur warna latar belakang elemen, sedangkan color mengatur warna teks.\"}, {\"answer\": \"Mengembalikan elemen berdasarkan ID\", \"options\": [\"Mengembalikan elemen berdasarkan nama kelas\", \"Mengembalikan elemen berdasarkan ID\", \"Mengembalikan koleksi elemen berdasarkan tag\", \"Mengembalikan elemen berdasarkan atribut name\"], \"question\": \"Apa fungsi dari method getElementById() dalam JavaScript?\", \"explanation\": \"getElementById() adalah method DOM yang mengembalikan elemen pertama dengan ID tertentu.\"}, {\"answer\": \"String\", \"options\": [\"Array\", \"Object\", \"String\", \"Function\"], \"question\": \"Manakah dari berikut ini yang merupakan tipe data primitif dalam JavaScript?\", \"explanation\": \"String adalah tipe data primitif, sedangkan Array, Object, dan Function termasuk tipe data kompleks (objek).\"}, {\"answer\": \"src\", \"options\": [\"src\", \"href\", \"link\", \"url\"], \"question\": \"Atribut HTML apa yang digunakan untuk menentukan URL gambar pada tag <img>?\", \"explanation\": \"Atribut src (source) pada tag <img> menentukan lokasi file gambar yang akan ditampilkan.\"}]', 'UAS', '2026-06-09 06:44:57'),
(45, 'Quv1ojcbZiS0QjT6IIsujK8rBWf1', 29, 'fokus ke framework js ya', 'SIA1', 'medium', 'multiple_choice', 5, '[{\"answer\": \"Representasi ringan dari DOM asli yang disimpan di memori untuk memperbarui UI secara efisien\", \"options\": [\"DOM asli yang dimanipulasi langsung oleh JavaScript\", \"Representasi ringan dari DOM asli yang disimpan di memori untuk memperbarui UI secara efisien\", \"DOM yang hanya digunakan pada server-side rendering\", \"DOM yang digunakan untuk mengelola event handling\"], \"question\": \"Apa yang dimaksud dengan Virtual DOM dalam framework React?\", \"explanation\": \"Virtual DOM adalah konsep di React di mana representasi virtual dari DOM disimpan di memori. Ketika state berubah, React membandingkan Virtual DOM baru dengan yang lama dan hanya memperbarui bagian yang berubah pada DOM asli, sehingga meningkatkan performa.\"}, {\"answer\": \"Data mengalir dua arah antara model dan view secara otomatis\", \"options\": [\"Data mengalir dari komponen induk ke anak saja\", \"Data mengalir dua arah antara model dan view secara otomatis\", \"Data hanya dapat diubah melalui event handling\", \"Data binding hanya terjadi pada saat render awal\"], \"question\": \"Dalam framework Vue.js, apa yang dimaksud dengan two-way data binding?\", \"explanation\": \"Two-way data binding di Vue.js memungkinkan perubahan pada model (data) secara otomatis tercermin ke view, dan sebaliknya perubahan pada view (misalnya input user) langsung memperbarui model. Ini diimplementasikan dengan direktif v-model.\"}, {\"answer\": \"Dependency Injection (DI)\", \"options\": [\"Props drilling\", \"Dependency Injection (DI)\", \"Context API\", \"Event Emitter\"], \"question\": \"Dalam Angular, mekanisme apa yang digunakan untuk menyediakan dependensi ke komponen atau service?\", \"explanation\": \"Angular menggunakan Dependency Injection (DI) sebagai pola desain untuk menyediakan dependensi (seperti service) ke komponen, directive, atau service lainnya. DI memungkinkan kode lebih modular, mudah diuji, dan dikelola.\"}, {\"answer\": \"Menangani routing dan navigasi antar halaman tanpa reload halaman penuh\", \"options\": [\"Mengelola state global aplikasi\", \"Menangani routing dan navigasi antar halaman tanpa reload halaman penuh\", \"Mengoptimalkan performa rendering dengan Virtual DOM\", \"Menyediakan binding data dua arah\"], \"question\": \"Apa fungsi utama dari React Router dalam aplikasi React?\", \"explanation\": \"React Router adalah library routing untuk React yang memungkinkan navigasi antar komponen (halaman) dalam aplikasi Single Page Application (SPA) tanpa perlu memuat ulang seluruh halaman dari server. Ini memanfaatkan URL dan history API.\"}, {\"answer\": \"Mengelola dan membagikan state antar komponen secara terpusat dan dapat diprediksi\", \"options\": [\"Mengelola dan membagikan state antar komponen secara terpusat dan dapat diprediksi\", \"Menggantikan Virtual DOM untuk meningkatkan performa\", \"Menangani routing dan navigasi\", \"Menyediakan fitur server-side rendering\"], \"question\": \"Dalam pengembangan aplikasi React, apa kegunaan utama dari state management seperti Redux atau Zustand?\", \"explanation\": \"State management seperti Redux atau Zustand digunakan untuk mengelola state global aplikasi yang perlu diakses oleh banyak komponen. Ini memudahkan debugging, testing, dan menjaga konsistensi data dengan aliran data satu arah (unidirectional).\"}]', 'fokus ke framework js ya', '2026-06-09 06:46:58'),
(46, 'Quv1ojcbZiS0QjT6IIsujK8rBWf1', 29, 'Variable Di Php', 'SIA1', 'medium', 'multiple_choice', 5, '[{\"answer\": \"$nama = \\\"Budi\\\";\", \"options\": [\"$nama = \\\"Budi\\\";\", \"var nama = \\\"Budi\\\";\", \"string nama = \\\"Budi\\\";\", \"nama = \\\"Budi\\\";\"], \"question\": \"Manakah cara yang benar untuk mendeklarasikan variabel di PHP?\", \"explanation\": \"Di PHP, variabel harus diawali dengan tanda dollar ($).\"}, {\"answer\": \"15\", \"options\": [\"105\", \"15\", \"10\", \"Error\"], \"question\": \"Apa yang akan dihasilkan oleh kode berikut?\\n$x = 10;\\n$y = 5;\\necho $x + $y;\", \"explanation\": \"Operator + menjumlahkan dua angka, sehingga 10 + 5 = 15.\"}, {\"answer\": \"isset($var)\", \"options\": [\"isset($var)\", \"defined($var)\", \"empty($var)\", \"is_set($var)\"], \"question\": \"Bagaimana cara mengecek apakah suatu variabel telah didefinisikan?\", \"explanation\": \"Fungsi isset() mengembalikan true jika variabel sudah didefinisikan dan tidak bernilai null.\"}, {\"answer\": \"$_nama\", \"options\": [\"$2nama\", \"$nama-saya\", \"$_nama\", \"$nama saya\"], \"question\": \"Manakah yang merupakan nama variabel valid di PHP?\", \"explanation\": \"Nama variabel PHP harus diawali huruf atau underscore, tidak boleh diawali angka atau mengandung spasi.\"}, {\"answer\": \"10\", \"options\": [\"10\", \"73\", \"7\", \"Error\"], \"question\": \"Apa output dari kode berikut?\\n$a = \\\"7\\\";\\n$b = 3;\\necho $a + $b;\", \"explanation\": \"PHP mengonversi string \\\"7\\\" menjadi integer 7, lalu menjumlahkannya dengan 3 sehingga hasilnya 10.\"}]', 'Variable Di Php', '2026-06-09 06:48:12'),
(47, 'Quv1ojcbZiS0QjT6IIsujK8rBWf1', 29, 'fokus ke framework js ya', 'SIA1', 'medium', 'essay', 5, '[{\"answer\": \"Virtual DOM adalah representasi ringan dari Real DOM yang disimpan dalam memori. React menggunakan Virtual DOM untuk membandingkan perubahan (diffing) dan hanya memperbarui bagian Real DOM yang benar-benar berubah, bukan seluruh halaman. Hal ini mengurangi manipulasi DOM yang mahal, sehingga meningkatkan performa aplikasi, terutama pada aplikasi dengan banyak perubahan data.\", \"question\": \"Jelaskan perbedaan antara Virtual DOM pada React dan Real DOM. Mengapa Virtual DOM dapat meningkatkan performa aplikasi?\", \"explanation\": \"Virtual DOM meminimalkan akses ke Real DOM dengan melakukan batch update.\"}, {\"answer\": \"Two-way data binding adalah mekanisme di mana perubahan pada data (model) secara otomatis memperbarui tampilan (view), dan sebaliknya, perubahan pada tampilan (misalnya input pengguna) langsung memperbarui data. Di Vue.js, ini diimplementasikan dengan direktif v-model. Contoh: <input v-model=\\\"message\\\"> akan mengikat nilai input ke properti data message, sehingga saat pengguna mengetik, message berubah, dan saat message diubah dari kode, input juga berubah.\", \"question\": \"Apa yang dimaksud dengan two-way data binding pada Vue.js? Berikan contoh penggunaannya dalam komponen.\", \"explanation\": \"v-model adalah sintaksis untuk two-way binding di Vue.\"}, {\"answer\": \"Dependency Injection (DI) adalah pola desain di mana sebuah kelas menerima dependensinya dari sumber eksternal, bukan menciptakannya sendiri. Di Angular, DI diimplementasikan melalui provider dan injector. Pengembang mendaftarkan service atau objek ke provider, lalu Angular menginjeksikannya ke komponen atau service lain melalui constructor. Contoh: constructor(private myService: MyService) { } akan menginjeksikan instance MyService. Ini memudahkan pengujian, pemeliharaan, dan pengelolaan dependensi.\", \"question\": \"Dalam Angular, terdapat konsep dependency injection. Jelaskan apa itu dependency injection dan bagaimana penerapannya dalam pengembangan aplikasi.\", \"explanation\": \"DI meningkatkan modularitas dan testabilitas kode.\"}, {\"answer\": \"Tiga lifecycle hooks utama di React: 1. componentDidMount (class) atau useEffect dengan [] (function) – dipanggil setelah komponen pertama kali dirender, cocok untuk fetch data. Contoh: useEffect(() => { fetchData(); }, []); 2. componentDidUpdate atau useEffect tanpa [] – dipanggil setiap kali ada update, digunakan untuk merespon perubahan props/state. 3. componentWillUnmount atau return cleanup di useEffect – dipanggil saat komponen dihapus, untuk membersihkan subscription atau timer. Contoh: useEffect(() => { const timer = setInterval(...); return () => clearInterval(timer); }, []);\", \"question\": \"Sebutkan dan jelaskan tiga lifecycle hooks utama pada React (misalnya componentDidMount, useEffect, dll) beserta contoh penggunaannya.\", \"explanation\": \"Lifecycle hooks mengontrol kapan efek samping dijalankan.\"}, {\"answer\": \"React dengan Context API menyediakan cara sederhana untuk berbagi state antar komponen tanpa prop drilling, tetapi kurang cocok untuk state yang sering berubah atau kompleks karena dapat menyebabkan re-render tidak perlu. Redux menawarkan state global yang terpusat dengan reducer dan actions, memudahkan debugging dan pengelolaan state besar, namun memerlukan boilerplate. Vuex di Vue mirip dengan Redux, dengan state, mutations, actions, dan getters, tetapi lebih terintegrasi dengan Vue dan lebih mudah dipahami karena menggunakan reaktivitas Vue. Kelebihan Vuex: lebih sedikit boilerplate, mudah diintegrasikan. Kekurangan: kurang fleksibel untuk kasus non-standar. Kelebihan Redux: ekosistem besar, middleware kuat. Kekurangan: kompleksitas tinggi.\", \"question\": \"Bandingkan pendekatan state management antara React (dengan Context API atau Redux) dan Vue (dengan Vuex). Apa kelebihan dan kekurangan masing-masing?\", \"explanation\": \"Pemilihan state management tergantung skala dan kompleksitas aplikasi.\"}]', 'fokus ke framework js ya', '2026-06-09 06:50:24'),
(48, 'Quv1ojcbZiS0QjT6IIsujK8rBWf1', 29, 'Variable Di Php', 'SIA1', 'medium', 'essay', 5, '[{\"answer\": \"$_nama = \\\"Budi\\\";\", \"options\": [\"$1nama = \\\"Budi\\\";\", \"$_nama = \\\"Budi\\\";\", \"$nama-saya = \\\"Budi\\\";\", \"var nama = \\\"Budi\\\";\"], \"question\": \"Manakah di antara berikut ini yang merupakan cara benar untuk mendeklarasikan sebuah variabel di PHP?\", \"explanation\": \"Variabel PHP harus diawali dengan tanda $ dan diikuti oleh huruf atau underscore. Nama variabel tidak boleh diawali angka atau mengandung tanda hubung. Opsi $_nama adalah satu-satunya yang memenuhi aturan tersebut.\"}, {\"answer\": \"20\", \"options\": [\"10\", \"20\", \"Error: variabel tidak terdefinisi\", \"Null\"], \"question\": \"Apa yang akan menjadi output dari kode PHP berikut?\\n\\n$x = 10;\\n$y = &$x;\\n$y = 20;\\necho $x;\", \"explanation\": \"Tanda & digunakan untuk membuat referensi. $y merujuk ke alamat memori yang sama dengan $x, sehingga mengubah $y juga mengubah $x. Outputnya adalah 20.\"}, {\"answer\": \"PHP secara otomatis menentukan tipe data berdasarkan nilai yang diberikan.\", \"options\": [\"Variabel harus dideklarasikan tipe datanya sebelum digunakan.\", \"PHP secara otomatis menentukan tipe data berdasarkan nilai yang diberikan.\", \"Tipe data variabel bersifat statis dan tidak dapat berubah.\", \"Variabel hanya dapat menyimpan satu tipe data sepanjang eksekusi.\"], \"question\": \"Manakah pernyataan yang benar mengenai tipe data variabel di PHP?\", \"explanation\": \"PHP adalah bahasa dengan tipe data dinamis (loosely typed). Variabel tidak perlu dideklarasikan tipe datanya, dan tipe data dapat berubah sesuai nilai yang diberikan.\"}, {\"answer\": \"Variabel lokal dideklarasikan di dalam sebuah fungsi dan hanya dapat diakses di dalam fungsi tersebut. Variabel global dideklarasikan di luar fungsi dan dapat diakses di mana saja setelah dideklarasikan, namun untuk mengaksesnya di dalam fungsi perlu menggunakan kata kunci \'global\' atau array $GLOBALS. Contoh:\\n\\n$globalVar = \\\"Global\\\";\\nfunction test() {\\n    $localVar = \\\"Lokal\\\";\\n    global $globalVar;\\n    echo $localVar; // Output: Lokal\\n    echo $globalVar; // Output: Global\\n}\\ntest();\\necho $globalVar; // Output: Global\\necho $localVar; // Error: undefined variable\", \"question\": \"Jelaskan perbedaan antara variabel lokal dan variabel global dalam PHP, serta berikan contoh kode singkat yang menunjukkan penggunaan keduanya.\", \"explanation\": \"Variabel lokal hanya ada selama fungsi dieksekusi, sedangkan variabel global ada sepanjang skrip. Penggunaan \'global\' diperlukan untuk mengakses variabel global dari dalam fungsi.\"}, {\"answer\": \"<?php\\n$var = \\\"10\\\"; // string\\n$var = (int)$var; // diubah menjadi integer\\n$hasil = $var + 5; // penjumlahan\\necho $hasil; // Output: 15\\n?>\\n\\nPHP secara otomatis melakukan type juggling (konversi tipe data) saat operasi aritmatika. Dalam contoh di atas, meskipun $var awalnya string, ketika dijumlahkan dengan integer, PHP mengonversi string ke integer. Dengan casting eksplisit (int), kita memastikan konversi terjadi.\", \"question\": \"Tuliskan kode PHP yang mendeklarasikan sebuah variabel bertipe string, kemudian mengubah nilainya menjadi integer, dan menampilkan hasil penjumlahan variabel tersebut dengan angka 5. Jelaskan bagaimana PHP menangani perubahan tipe data tersebut.\", \"explanation\": \"PHP memiliki fitur type juggling yang memungkinkan konversi tipe data secara otomatis. Casting eksplisit memberikan kontrol lebih kepada programmer.\"}]', 'Variable Di Php', '2026-06-09 06:52:50');
INSERT INTO `questions` (`id`, `user_id`, `subject_id`, `title`, `class`, `difficulty`, `type`, `total_questions`, `questions_data`, `prompt_used`, `created_at`) VALUES
(49, 'Quv1ojcbZiS0QjT6IIsujK8rBWf1', 44, 'UAS TEBAKAN KOCAK', 'Kocak', 'hard', 'multiple_choice', 20, '[{\"answer\": \"Plastik kopi\", \"options\": [\"Ikan asin\", \"Surat cinta\", \"Plastik kopi\", \"Tisu bekas\"], \"question\": \"Bapak-bapak lagi ngopi di teras, tiba-tiba ada kucing lewat sambil bawa bungkusan. Kira-kira bungkusan itu isinya apa?\", \"explanation\": \"Kucing itu ternyata bapak-bapak yang lagi nyari tempat buang bungkus kopi.\"}, {\"answer\": \"Supaya gelasnya nggak terbang\", \"options\": [\"Biar kelihatan keren\", \"Supaya gelasnya nggak terbang\", \"Karena tangannya dingin\", \"Biar ada alasan buat nggak salaman\"], \"question\": \"Kenapa bapak-bapak kalau lagi ngobrol di warung selalu sambil megang gelas?\", \"explanation\": \"Soalnya gelasnya sering dipake buat ngeloyor kalau ada tagihan.\"}, {\"answer\": \"Bilang \'ah nanti juga ada rezeki\'\", \"options\": [\"Nangis di pojokan\", \"Bilang \'ah nanti juga ada rezeki\'\", \"Langsung minum kopi\", \"Minta ke istri\"], \"question\": \"Apa yang dilakukan bapak-bapak saat melihat dompetnya kosong?\", \"explanation\": \"Itu jawaban standar bapak-bapak biar kelihatan ikhlas, padahal hatinya remuk.\"}, {\"answer\": \"Pura-pura nelpon\", \"options\": [\"Lari cepet\", \"Pura-pura nelpon\", \"Nunduk sambil ngebut\", \"Nyapa polisi dengan senyum\"], \"question\": \"Bapak-bapak lagi jalan kaki, tiba-tiba ada polisi lalu lintas. Apa yang pertama kali dia lakukan?\", \"explanation\": \"Biar kelihatan sibuk, padahal nggak ada yang ditelepon.\"}, {\"answer\": \"Karena bikin dompet kering\", \"options\": [\"Karena bikin motor jalan\", \"Karena baunya wangi\", \"Karena bisa dijual lagi\", \"Karena bikin dompet kering\"], \"question\": \"Kenapa bapak-bapak suka banget sama bensin?\", \"explanation\": \"Bensin = uang keluar terus, jadi dompet kering.\"}, {\"answer\": \"\'Saya bayar ntar ya, Pak\'\", \"options\": [\"\'Saya bayar ntar ya, Pak\'\", \"\'Wah, ketinggalan dompet nih\'\", \"\'Saya traktir dulu, besok ganti\'\", \"\'Bapak yang traktir, ya\'\"], \"question\": \"Apa yang diucapkan bapak-bapak saat lupa bawa duit pas mau bayar kopi?\", \"explanation\": \"Ini kode \'saya ngutang dulu\' yang sudah jadi budaya.\"}, {\"answer\": \"Ngumpat sambil gigit jari\", \"options\": [\"Nyalain lilin\", \"Ngumpat sambil gigit jari\", \"Lanjut nonton lewat hape\", \"Tidur\"], \"question\": \"Bapak-bapak lagi nonton bola di TV, tiba-tiba listrik padam. Apa yang dia lakukan?\", \"explanation\": \"Kesel tapi nggak bisa ngapa-ngapain, makanya gigit jari.\"}, {\"answer\": \"Biar kelihatan sibuk\", \"options\": [\"Buat bawa belanjaan\", \"Buat tempat sampah\", \"Buat jaga-jaga kalau hujan\", \"Biar kelihatan sibuk\"], \"question\": \"Kenapa bapak-bapak kalau ke pasar selalu bawa kresek?\", \"explanation\": \"Padahal isinya cuma kresek kosong, biar istri nggak nyuruh masak.\"}, {\"answer\": \"Bapak-bapak teriak \'kopi\', tukang parkir teriak \'maju\'\", \"options\": [\"Sama-sama suka teriak\", \"Bapak-bapak teriak \'kopi\', tukang parkir teriak \'maju\'\", \"Bapak-bapak bawa gelas, tukang parkir bawa rompi\", \"Nggak ada bedanya\"], \"question\": \"Apa bedanya bapak-bapak dengan tukang parkir?\", \"explanation\": \"Keduanya hobi teriak, tapi beda objek.\"}, {\"answer\": \"Turun sambil bengong\", \"options\": [\"Ganti ban sendiri\", \"Telepon bengkel\", \"Nunggu ada yang bantuin\", \"Turun sambil bengong\"], \"question\": \"Bapak-bapak lagi di mobil, tiba-tiba ban kempes. Apa yang dia lakukan?\", \"explanation\": \"Biar kelihatan pusing, padahal nggak ngerti cara ganti ban.\"}, {\"answer\": \"Karena di rumah disuruh istri\", \"options\": [\"Karena kopinya enak\", \"Karena bisa ngobrol gratis\", \"Karena bisa liat orang lewat\", \"Karena di rumah disuruh istri\"], \"question\": \"Kenapa bapak-bapak suka ngumpul di warung kopi?\", \"explanation\": \"Biar nggak kena marah, mending ngumpul di warung.\"}, {\"answer\": \"Pura-pura sibuk\", \"options\": [\"Diam seribu bahasa\", \"Minta maaf\", \"Keluar rumah\", \"Pura-pura sibuk\"], \"question\": \"Apa yang dilakukan bapak-bapak saat istrinya lagi marah?\", \"explanation\": \"Biar dikira kerja, padahal lagi scroll HP.\"}, {\"answer\": \"Marah-marah sama korannya\", \"options\": [\"Nempel pake selotip\", \"Baca halaman lain\", \"Nggak peduli\", \"Marah-marah sama korannya\"], \"question\": \"Bapak-bapak lagi baca koran, tiba-tiba halaman tengah sobek. Apa yang dia lakukan?\", \"explanation\": \"Korannya dianggap salah karena sobek, padahal bapak yang narik terlalu keras.\"}, {\"answer\": \"Biar nggak kelihatan kalau ketiduran\", \"options\": [\"Biar cepet pulang\", \"Biar nggak kelihatan kalau ketiduran\", \"Karena depan penuh\", \"Karena suka nyender tembok\"], \"question\": \"Kenapa bapak-bapak kalau lagi ngantuk di masjid selalu duduk di barisan belakang?\", \"explanation\": \"Di belakang lebih aman kalau tiba-tiba kepala nyungsep.\"}, {\"answer\": \"\'Tapi uangnya ada?\'\", \"options\": [\"\'Ayo sayang\'\", \"\'Ntar ya, lagi sibuk\'\", \"\'Tapi uangnya ada?\'\", \"\'Males ah\'\"], \"question\": \"Apa yang diucapkan bapak-bapak saat diajak jalan-jalan sama istri?\", \"explanation\": \"Pertanyaan paling sering keluar sebelum mutusin pergi.\"}, {\"answer\": \"Nanya \'sehat, Pak?\'\", \"options\": [\"Diam aja\", \"Nanya \'sehat, Pak?\'\", \"Pindah kursi\", \"Minta berhenti dulu\"], \"question\": \"Bapak-bapak lagi potong rambut, tiba-tiba tukang cukur batuk. Apa yang dia lakukan?\", \"explanation\": \"Biar kelihatan peduli, padahal takut rambutnya dipotong salah.\"}, {\"answer\": \"Karena botolnya bisa dipake lagi\", \"options\": [\"Karena murah\", \"Karena bisa dicampur bensin\", \"Karena botolnya bisa dipake lagi\", \"Karena bisa buat goreng ikan\"], \"question\": \"Kenapa bapak-bapak suka beli minyak goreng curah?\", \"explanation\": \"Botol bekas minyak goreng bisa dipake buat simpan bensin atau oli.\"}, {\"answer\": \"Ngomong \'ah, nggak penting\'\", \"options\": [\"Maksa baca\", \"Pinjem kacamata teman\", \"Ngomong \'ah, nggak penting\'\", \"Pulang ambil kacamata\"], \"question\": \"Apa yang dilakukan bapak-bapak saat lupa bawa kacamata?\", \"explanation\": \"Biar kelihatan nggak butuh, padahal matanya udah juling.\"}, {\"answer\": \"Pura-pura nunggu orang\", \"options\": [\"Naik kereta\", \"Nunggu kereta berikutnya\", \"Makan dulu\", \"Pura-pura nunggu orang\"], \"question\": \"Bapak-bapak lagi di stasiun, tiba-tiba kereta datang. Apa yang dia lakukan?\", \"explanation\": \"Biar nggak kelihatan bingung, padahal nggak tau mau naik kereta mana.\"}, {\"answer\": \"Buat alas duduk\", \"options\": [\"Buat baca\", \"Buat alas duduk\", \"Buat ngelap keringat\", \"Biar kelihatan sibuk\"], \"question\": \"Kenapa bapak-bapak suka bawa koran ke toilet?\", \"explanation\": \"Soalnya dudukan toilet biasanya dingin, koran jadi solusi.\"}]', 'UAS TEBAKAN KOCAK', '2026-06-09 13:32:11'),
(50, 'Quv1ojcbZiS0QjT6IIsujK8rBWf1', 44, 'fokus ke framework js ya', 'Kocak', 'medium', 'multiple_choice', 5, '[{\"answer\": \"React\", \"options\": [\"React\", \"Angular\", \"Vue\", \"Svelte\"], \"question\": \"Framework JS apa yang paling suka bercanda?\", \"explanation\": \"Karena React itu reaktif, jadi suka bercanda kalau ada event.\"}, {\"answer\": \"Karena dia selalu ngomong sendiri\", \"options\": [\"Karena dia terlalu strict\", \"Karena dia pake TypeScript\", \"Karena dia selalu ngomong sendiri\", \"Karena dia pake module\"], \"question\": \"Kenapa Angular tidak pernah mau diajak main tebak-tebakan?\", \"explanation\": \"Angular punya dependency injection, jadi asyik ngobrol sama dirinya sendiri.\"}, {\"answer\": \"Vue\", \"options\": [\"React\", \"Angular\", \"Vue\", \"Svelte\"], \"question\": \"Framework JS apa yang paling jago main petak umpet?\", \"explanation\": \"Vue itu ringan dan cepat, jadi gampang sembunyi di balik komponen.\"}, {\"answer\": \"Compile ulang\", \"options\": [\"Nulis kode\", \"Compile ulang\", \"Nangis di terminal\", \"Makan ice cream\"], \"question\": \"Apa yang dilakukan Svelte saat lagi galau?\", \"explanation\": \"Svelte suka compile ulang biar fresh lagi.\"}, {\"answer\": \"Vue-lverine\", \"options\": [\"React-Man\", \"Angular Woman\", \"Vue-lverine\", \"Svelte-tastic\"], \"question\": \"Kalau framework JS jadi superhero, siapa yang paling kuat?\", \"explanation\": \"Vue punya claws (computed) yang tajam.\"}]', 'fokus ke framework js ya', '2026-06-09 14:06:53'),
(51, 'Quv1ojcbZiS0QjT6IIsujK8rBWf1', 29, 'Variable Di Php', 'Kocak', 'medium', 'multiple_choice', 5, '[{\"answer\": \"$nama = \\\"Budi\\\";\", \"options\": [\"$nama = \\\"Budi\\\";\", \"var nama = \\\"Budi\\\";\", \"dim nama as string = \\\"Budi\\\";\", \"string nama = \\\"Budi\\\";\"], \"question\": \"Manakah cara yang benar untuk mendeklarasikan variabel di PHP?\", \"explanation\": \"Di PHP, variabel diawali dengan tanda $, lalu nama variabel. Tidak perlu tipe data eksplisit.\"}, {\"answer\": \"10\", \"options\": [\"10\", \"55\", \"Error\", \"5\"], \"question\": \"Apa output dari echo $x; jika $x = 5 + \\\"5\\\";?\", \"explanation\": \"PHP secara otomatis mengonversi string \\\"5\\\" menjadi angka 5, sehingga hasil penjumlahan adalah 10.\"}, {\"answer\": \"$2nama\", \"options\": [\"$_nama\", \"$2nama\", \"$nama_saya\", \"$Nama\"], \"question\": \"Manakah yang BUKAN nama variabel valid di PHP?\", \"explanation\": \"Nama variabel PHP harus diawali dengan huruf atau underscore, tidak boleh angka.\"}, {\"answer\": \"isset($var)\", \"options\": [\"isset($var)\", \"defined($var)\", \"exist($var)\", \"isSet($var)\"], \"question\": \"Bagaimana cara mengecek apakah suatu variabel telah didefinisikan?\", \"explanation\": \"Fungsi isset() digunakan untuk memeriksa apakah variabel sudah didefinisikan dan tidak bernilai null.\"}, {\"answer\": \"Variabel yang hanya bisa diakses di dalam fungsi tersebut\", \"options\": [\"Variabel yang bisa diakses dari mana saja\", \"Variabel yang hanya bisa diakses di dalam fungsi tersebut\", \"Variabel yang dideklarasikan dengan global\", \"Variabel yang otomatis tersedia\"], \"question\": \"Apa yang dimaksud dengan variabel lokal di dalam fungsi?\", \"image_url\": \"/public/assets/question/images/q_1781014489_223bfec4.png\", \"explanation\": \"Variabel lokal hanya dikenal di dalam fungsi tempat ia dideklarasikan, tidak dapat diakses dari luar fungsi.\"}]', 'Variable Di Php', '2026-06-09 14:12:37'),
(52, 'Quv1ojcbZiS0QjT6IIsujK8rBWf1', 29, 'fokus ke framework js ya', 'SIA1', 'medium', 'multiple_choice', 5, '[{\"answer\": \"Representasi ringan dari DOM asli yang disimpan di memori untuk memperbarui UI secara efisien\", \"options\": [\"DOM asli yang dimanipulasi langsung oleh JavaScript\", \"Representasi ringan dari DOM asli yang disimpan di memori untuk memperbarui UI secara efisien\", \"DOM yang hanya digunakan pada server-side rendering\", \"DOM yang digunakan untuk mengelola event handling\"], \"question\": \"Apa yang dimaksud dengan Virtual DOM dalam framework React?\", \"explanation\": \"Virtual DOM adalah konsep di React di mana representasi virtual dari DOM disimpan di memori. Ketika state berubah, React membandingkan Virtual DOM baru dengan yang lama dan hanya memperbarui bagian yang berubah pada DOM asli, sehingga meningkatkan performa.\"}, {\"answer\": \"Data mengalir dua arah antara model dan view secara otomatis\", \"options\": [\"Data mengalir dari komponen induk ke anak saja\", \"Data mengalir dua arah antara model dan view secara otomatis\", \"Data hanya dapat diubah melalui event handling\", \"Data binding hanya terjadi pada saat render awal\"], \"question\": \"Dalam framework Vue.js, apa yang dimaksud dengan two-way data binding?\", \"explanation\": \"Two-way data binding di Vue.js memungkinkan perubahan pada model (data) secara otomatis tercermin ke view, dan sebaliknya perubahan pada view (misalnya input user) langsung memperbarui model. Ini diimplementasikan dengan direktif v-model.\"}, {\"answer\": \"Dependency Injection (DI)\", \"options\": [\"Props drilling\", \"Dependency Injection (DI)\", \"Context API\", \"Event Emitter\"], \"question\": \"Dalam Angular, mekanisme apa yang digunakan untuk menyediakan dependensi ke komponen atau service?\", \"explanation\": \"Angular menggunakan Dependency Injection (DI) sebagai pola desain untuk menyediakan dependensi (seperti service) ke komponen, directive, atau service lainnya. DI memungkinkan kode lebih modular, mudah diuji, dan dikelola.\"}, {\"answer\": \"Menangani routing dan navigasi antar halaman tanpa reload halaman penuh\", \"options\": [\"Mengelola state global aplikasi\", \"Menangani routing dan navigasi antar halaman tanpa reload halaman penuh\", \"Mengoptimalkan performa rendering dengan Virtual DOM\", \"Menyediakan binding data dua arah\"], \"question\": \"Apa fungsi utama dari React Router dalam aplikasi React?\", \"explanation\": \"React Router adalah library routing untuk React yang memungkinkan navigasi antar komponen (halaman) dalam aplikasi Single Page Application (SPA) tanpa perlu memuat ulang seluruh halaman dari server. Ini memanfaatkan URL dan history API.\"}, {\"answer\": \"Mengelola dan membagikan state antar komponen secara terpusat dan dapat diprediksi\", \"options\": [\"Mengelola dan membagikan state antar komponen secara terpusat dan dapat diprediksi\", \"Menggantikan Virtual DOM untuk meningkatkan performa\", \"Menangani routing dan navigasi\", \"Menyediakan fitur server-side rendering\"], \"question\": \"Dalam pengembangan aplikasi React, apa kegunaan utama dari state management seperti Redux atau Zustand?\", \"explanation\": \"State management seperti Redux atau Zustand digunakan untuk mengelola state global aplikasi yang perlu diakses oleh banyak komponen. Ini memudahkan debugging, testing, dan menjaga konsistensi data dengan aliran data satu arah (unidirectional).\"}]', 'fokus ke framework js ya', '2026-06-09 14:15:13'),
(53, 'Quv1ojcbZiS0QjT6IIsujK8rBWf1', 44, 'fokus ke framework js ya', 'Kocak', 'easy', 'multiple_choice', 5, '[{\"answer\": \"React\", \"options\": [\"React\", \"Vue\", \"Angular\", \"Svelte\"], \"question\": \"Framework JS apa yang paling suka ngopi?\", \"explanation\": \"Karena React itu \'re-aktif\' kalau dikasih kopi, langsung aktif!\"}, {\"answer\": \"Vue\", \"options\": [\"Vue\", \"React\", \"Angular\", \"Svelte\"], \"question\": \"Framework JS mana yang paling suka ngintip?\", \"explanation\": \"Vue itu \'view\' alias ngintip, makanya suka liat-liat.\"}, {\"answer\": \"Angular\", \"options\": [\"Angular\", \"React\", \"Vue\", \"Svelte\"], \"question\": \"Framework JS apa yang bentuknya kayak ular?\", \"explanation\": \"Angular bunyinya \'anguler\' mirip ular melingkar.\"}, {\"answer\": \"Svelte123\", \"options\": [\"Svelte123\", \"React123\", \"Vue123\", \"Angular123\"], \"question\": \"Framework JS mana yang paling kurus?123\", \"image_url\": \"/public/assets/question/images/q_1781016250_e83ec0bf.png\", \"explanation\": \"Svelte artinya ramping, cocok buat yang lagi diet kode.123\"}, {\"answer\": \"Next.js\", \"options\": [\"Next.js\", \"Nuxt.js\", \"Gatsby\", \"VueJs\"], \"question\": \"Framework JS apa yang suka banget sama halaman?\", \"image_url\": null, \"explanation\": \"Next.js \'next page\' terus, makanya demen pindah halaman.\"}]', 'fokus ke framework js ya', '2026-06-09 14:43:50');

